"use client";
import * as HoverCardPrimitive from "@radix-ui/react-hover-card";
import { encode } from "qss";
import React from "react";
import {
  AnimatePresence,
  motion,
  useMotionValue,
  useSpring,
} from "framer-motion";
import { cn } from "../../lib/utils";

type LinkPreviewProps = {
  children: React.ReactNode;
  url: string;
  className?: string;
  width?: number;
  height?: number;
  quality?: number;
  layout?: string;
} & (
  | { isStatic: true; imageSrc: string }
  | { isStatic?: false; imageSrc?: never }
);

export const LinkPreview = ({
  children,
  url,
  className,
  width = 200,
  height = 125,
  quality = 50,
  layout = "fixed",
  isStatic = false,
  imageSrc = "",
}: LinkPreviewProps) => {
  let src;
  if (!isStatic) {
    const params = encode({
      url,
      screenshot: true,
      meta: false,
      embed: "screenshot.url",
      colorScheme: "dark",
      "viewport.isMobile": true,
      "viewport.deviceScaleFactor": 1,
      "viewport.width": width * 3,
      "viewport.height": height * 3,
    });
    src = `https://api.microlink.io/?${params}`;
  } else {
    src = imageSrc;
  }

  const [isOpen, setOpen] = React.useState(false);

  const [isMounted, setIsMounted] = React.useState(false);

  React.useEffect(() => {
    setIsMounted(true);
  }, []);

  const springConfig = { stiffness: 100, damping: 15 };
  const x = useMotionValue(0);

  const translateX = useSpring(x, springConfig);

  const handleMouseMove = (event: any) => {
    const targetRect = event.target.getBoundingClientRect();
    const eventOffsetX = event.clientX - targetRect.left;
    const offsetFromCenter = (eventOffsetX - targetRect.width / 2) / 2; // Reduce the effect to make it subtle
    x.set(offsetFromCenter);
  };

  return (
    <>
      {isMounted ? (
        <span hidden>
          <img
            src={src}
            width={width}
            height={height}
            alt="hidden image"
          />
        </span>
      ) : null}

      <HoverCardPrimitive.Root
        openDelay={50}
        closeDelay={100}
        onOpenChange={(open) => {
          setOpen(open);
        }}
      >
        <HoverCardPrimitive.Trigger
          onMouseMove={handleMouseMove}
          className={cn("text-black dark:text-white", className)}
          href={url}
        >
          {children}
        </HoverCardPrimitive.Trigger>

        <HoverCardPrimitive.Content
          className="[transform-origin:var(--radix-hover-card-content-transform-origin)]"
          side="top"
          align="center"
          sideOffset={10}
        >
          <AnimatePresence>
            {isOpen && (
              <motion.div
                initial={{ opacity: 0, y: 20, scale: 0.6 }}
                animate={{
                  opacity: 1,
                  y: 0,
                  scale: 1,
                  transition: {
                    type: "spring",
                    stiffness: 260,
                    damping: 20,
                  },
                }}
                exit={{ opacity: 0, y: 20, scale: 0.6 }}
                className="shadow-xl rounded-xl"
                style={{
                  x: translateX,
                }}
              >
                <a
                  href={url}
                  className="block p-1 bg-white border-2 border-transparent shadow rounded-xl hover:border-neutral-200 dark:hover:border-neutral-800"
                  style={{ fontSize: 0 }}
                >
                  <img
                    src={isStatic ? imageSrc : src}
                    width={width}
                    height={height}
                    className="rounded-lg"
                    alt="preview image"
                  />
                </a>
              </motion.div>
            )}
          </AnimatePresence>
        </HoverCardPrimitive.Content>
      </HoverCardPrimitive.Root>
    </>
  );
};

import { useEffect, useState } from 'react';
import { Loader2, ShieldAlert } from '../../components/icons';
import { AdminDashboard } from './AdminDashboard';
import { useStore } from '../../store/useStore';
import { supabase, isSupabaseConfigured } from '../../services/supabase/client';
import { CrystalLoader } from '../../components/ui/CrystalLoader';

const OWNER_EMAIL = 'wajih.souissi.ws@gmail.com';

type GateState =
    | { kind: 'checking' }
    | { kind: 'allowed' }
    | { kind: 'denied'; reason: string };

export default function AdminGate() {
    const setCurrentView = useStore((s) => s.setCurrentView);
    const [state, setState] = useState<GateState>({ kind: 'checking' });

    useEffect(() => {
        let cancelled = false;

        const redirectHome = () => {
            window.history.replaceState({}, '', '/');
            setCurrentView('marketing');
        };

        const verifyOwner = async () => {
            if (!isSupabaseConfigured || !supabase) {
                setState({ kind: 'denied', reason: 'Supabase is not configured.' });
                window.setTimeout(redirectHome, 900);
                return;
            }

            const { data: authData, error: authError } = await supabase.auth.getUser();
            const activeUser = authData.user;
            if (cancelled) return;

            if (authError || !activeUser) {
                setState({ kind: 'denied', reason: 'Owner session required.' });
                window.setTimeout(redirectHome, 900);
                return;
            }

            const sessionEmail = activeUser.email ?? '';
            const verifiedEmail = sessionEmail.trim().toLowerCase();

            if (verifiedEmail !== OWNER_EMAIL) {
                setState({ kind: 'denied', reason: 'Owner account required.' });
                window.setTimeout(redirectHome, 900);
                return;
            }

            setState({ kind: 'allowed' });
        };

        void verifyOwner();

        return () => {
            cancelled = true;
        };
    }, [setCurrentView]);

    if (state.kind === 'allowed') {
        return <AdminDashboard ownerEmail={OWNER_EMAIL} />;
    }

    if (state.kind === 'checking') {
        return (
            <div style={{
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                minHeight: '100vh', width: '100%', backgroundColor: 'var(--bg-base)'
            }}>
                <CrystalLoader />
            </div>
        );
    }

    return (
        <div
            style={{
                minHeight: '100vh',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                background: '#f6f4ef',
                color: '#161616',
                fontFamily: '"Poppins", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
                padding: 24,
            }}
        >
            <div
                style={{
                    width: 'min(420px, 100%)',
                    border: '1px solid rgba(22,22,22,0.1)',
                    background: 'rgba(255,255,255,0.78)',
                    boxShadow: '0 18px 60px rgba(20, 20, 20, 0.08)',
                    borderRadius: 12,
                    padding: 28,
                    textAlign: 'center',
                }}
            >
                <ShieldAlert size={30} style={{ margin: '0 auto 14px', color: '#dc2626' }} />
                <h1 style={{ fontSize: 18, margin: 0 }}>Access denied</h1>
                <p style={{ margin: '8px 0 0', color: 'rgba(22,22,22,0.58)', fontSize: 13 }}>
                    {state.reason}
                </p>
            </div>
        </div>
    );

}

