import { useState, useCallback, useEffect } from 'react';
import { useStore } from '../../../store/useStore';
import { defaultIconName } from '../iconMap';
import type { NoteData } from '../../../types';

interface NoteMetadataState {
    label: string;
    icon: string;
    description: string;
    category: string;
    coverImage: string;
    date: string;
}

interface UseNoteMetadataOptions {
    id: string;
    data: {
        label?: string;
        icon?: string;
        description?: string;
        category?: string;
        coverImage?: string;
        date?: string;
    } | null;
    onUpdate: (id: string, data: Partial<NoteData>) => void;
}

/**
 * Hook that manages metadata editing state and handlers for notes.
 * Handles icon selection, title editing, and metadata save operations.
 */
export function useNoteMetadata({ id, data, onUpdate }: UseNoteMetadataOptions) {
    const activeIconMenuId = useStore(s => s.activeIconMenuId);
    const setActiveIconMenuId = useStore(s => s.setActiveIconMenuId);

    const [isEditingMetadata, setIsEditingMetadata] = useState(false);
    const [showCoverPicker, setShowCoverPicker] = useState(false);

    const [editedData, setEditedData] = useState<NoteMetadataState>({
        label: data?.label || 'Untitled',
        icon: data?.icon || defaultIconName,
        description: data?.description || '',
        category: data?.category || '',
        coverImage: data?.coverImage || '',
        date: data?.date || new Date().toISOString()
    });

    // Update local state when data prop changes (e.g. from external updates)
    useEffect(() => {
        if (!isEditingMetadata && data) {
            setEditedData({
                label: data.label || 'Untitled',
                icon: data.icon || defaultIconName,
                description: data.description || '',
                category: data.category || '',
                coverImage: data.coverImage || '',
                date: data.date || new Date().toISOString()
            });
        }
    }, [data]);

    const handleSaveMetadata = useCallback(() => {
        onUpdate(id, editedData);
        setIsEditingMetadata(false);
    }, [id, editedData, onUpdate]);

    const handleIconSelect = useCallback((icon: string) => {
        setEditedData(prev => ({ ...prev, icon }));
        if (!isEditingMetadata) {
            onUpdate(id, { icon });
        }
        setActiveIconMenuId(null);
    }, [id, isEditingMetadata, onUpdate, setActiveIconMenuId]);

    const handleIconClick = useCallback((e: React.MouseEvent) => {
        e.stopPropagation();
        setActiveIconMenuId(id);
    }, [id, setActiveIconMenuId]);

    const handleCoverSelect = useCallback((url: string) => {
        onUpdate(id, { coverImage: url });
        setShowCoverPicker(false);
    }, [id, onUpdate]);

    const showIconPicker = activeIconMenuId === id;

    return {
        editedData,
        setEditedData,
        isEditingMetadata,
        setIsEditingMetadata,
        showCoverPicker,
        setShowCoverPicker,
        showIconPicker,
        handleSaveMetadata,
        handleIconSelect,
        handleIconClick,
        handleCoverSelect,
        setActiveIconMenuId,
    };
}

import { useState, useRef, useEffect, type ElementType } from 'react';
import { Plus, Calendar, Link2, User, LayoutList, Text, Flag, BarChart3 } from '../../../components/icons';
import styles from './Properties.module.css';

interface AddPropertyMenuProps {
    availableProperties: Array<{
        key: string;
        label: string;
        icon: ElementType;
    }>;
    onAdd: (key: string) => void;
}

export function AddPropertyMenu({ availableProperties, onAdd }: AddPropertyMenuProps) {
    const [isOpen, setIsOpen] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        }
        if (isOpen) document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isOpen]);

    // Always render, even if empty (show "No more properties")

    return (
        <div className={styles.addPropertyContainer} ref={containerRef} style={{ position: 'relative' }}>
            <button
                className={styles.addPropertyBtn}
                onClick={() => setIsOpen(!isOpen)}
            >
                <Plus size={14} />
                Add Property
            </button>

            {isOpen && (
                <div className={styles.popover} style={{ width: '220px' }}>
                    <div style={{ padding: '6px 8px', fontSize: '11px', fontWeight: 600, color: 'var(--color-text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                        Properties
                    </div>
                    {availableProperties.length > 0 ? (
                        availableProperties.map(prop => (
                            <div
                                key={prop.key}
                                className={styles.menuItem}
                                onClick={() => {
                                    onAdd(prop.key);
                                    setIsOpen(false);
                                }}
                            >
                                <prop.icon size={14} className={styles.menuIcon} style={{ opacity: 0.7 }} />
                                {prop.label}
                            </div>
                        ))
                    ) : (
                        <div style={{ padding: '8px', fontSize: '0.8rem', color: 'var(--color-text-muted)', textAlign: 'center', fontStyle: 'italic' }}>
                            No more properties
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

// Helper to get icon for property type
export const getPropertyIcon = (key: string) => {
    switch (key) {
        case 'status': return LayoutList;
        case 'priority': return Flag;
        case 'startDate': return Calendar;
        case 'dueDate': return Calendar;
        case 'url': return Link2;
        case 'assignee': return User;
        case 'progress': return BarChart3;
        case 'tasks': return LayoutList;
        default: return Text;
    }
};

