            }
            return;
        }

        // Ctrl+Enter - Add block below and focus
        if (isCtrl && e.key === 'Enter') {
            e.preventDefault();
            addBlockBelow(id);
            return;
        }

        if (e.key === 'Tab') {
            e.preventDefault();
            if (e.shiftKey) {
