                        : 'text';
                    const indent = currentBlock?.indent || 0;

                    // Update current node's content
                    const newBlocks = [...blocksRef.current];
                    const index = newBlocks.findIndex(b => b.id === id);
                    if (index !== -1) {
                        newBlocks[index] = { ...newBlocks[index], content: textBefore };
