            if (getCaretOffset() === content.length) {
                const index = blocksRef.current.findIndex(b => b.id === id);
                if (index < blocksRef.current.length - 1) {
                    e.preventDefault();
                    const nextBlock = blocksRef.current[index + 1];

                    // Check if next block is non-textual
                    const nonTextTypes = ['media', 'image', 'video', 'file', 'gallery', 'divider', 'columns', 'table', 'page'];
                    if (nonTextTypes.includes(nextBlock.type)) {
                        // If next block is a media or container, just focus it or delete it if it is a divider
                        if (nextBlock.type === 'divider') {
                            removeBlock(nextBlock.id);
                        } else {
                            setFocusId(nextBlock.id);
                        }
                        return;
                    }

                    const currentLength = content.length;
                    setBlocks(prev => {
                        const newBlocks = [...prev];
                        newBlocks.splice(index + 1, 1);
                        newBlocks[index] = {
                            ...prev[index], // Use fresh current
                            content: prev[index].content + nextBlock.content
                        };
                        debouncedOnUpdate(newBlocks);
                        return newBlocks;
                    });
                    caretPositionRef.current = currentLength;
                    setFocusId(id);
                }
            }
        } else if (e.key === 'ArrowUp') {
            if (e.shiftKey) {
                // If at start of block (offset 0), select previous block + current
                if (getCaretOffset() === 0) {
                    e.preventDefault();
                    // If not already in selection mode, include current + prev
                    // If already, extend upwards
                    const currentIndex = blocksRef.current.findIndex(b => b.id === id);
                    if (currentIndex > 0) {
                        const newSelection = new Set(selectedBlockIdsRef.current);
                        newSelection.add(id);
                        newSelection.add(blocksRef.current[currentIndex - 1].id);
                        setSelectedBlockIds(newSelection);
                        // Blur text to show block selection clearly?
                        if (document.activeElement instanceof HTMLElement) document.activeElement.blur();
                        editorRef.current?.focus({ preventScroll: true }); // Focus container to capture next arrows
                    }
                }
            } else {
                // Block navigation: Arrow Up at first line or empty block -> focus previous
                if (content === '' || checkCaretFirstLine()) {
                    const currentIndex = blocksRef.current.findIndex(b => b.id === id);
                    if (currentIndex > 0) {
                        e.preventDefault();
                        
                        // Find previous VISIBLE block
                        let prevVisibleIndex = currentIndex - 1;
                        while (prevVisibleIndex >= 0) {
                            const b = blocksRef.current[prevVisibleIndex];
                            // Check if this block is hidden by some parent toggle
                            let isHidden = false;
                            for (let i = 0; i < prevVisibleIndex; i++) {
                                const parent = blocksRef.current[i];
                                if (parent.type === 'toggle' && parent.metadata?.isCollapsed && (b.indent || 0) > (parent.indent || 0)) {
                                    isHidden = true;
                                    break;
                                }
                            }
                            if (!isHidden) break;
                            prevVisibleIndex--;
                        }

                        if (prevVisibleIndex >= 0) {
                            const x = getCaretX();
                            const fallbackOffset = getCaretOffset();
                            if (x !== null) {
                                caretPositionRef.current = { x, line: 'last', fallbackOffset };
                            } else {
                                caretPositionRef.current = fallbackOffset;
                            }
                            setFocusId(blocksRef.current[prevVisibleIndex].id);
                        }
                    }
                }
            }
        } else if (e.key === 'ArrowDown') {
            if (e.shiftKey) {
                // If at end of block, select next block + current
                if (getCaretOffset() === content.length) {
                    e.preventDefault();
                    const currentIndex = blocksRef.current.findIndex(b => b.id === id);
                    if (currentIndex < blocksRef.current.length - 1) {
                        const newSelection = new Set(selectedBlockIdsRef.current);
                        newSelection.add(id);
                        newSelection.add(blocksRef.current[currentIndex + 1].id);
                        setSelectedBlockIds(newSelection);
                        if (document.activeElement instanceof HTMLElement) document.activeElement.blur();
                        editorRef.current?.focus({ preventScroll: true });
                    }
                }
            } else {
                // Block navigation: Arrow Down at last line of block -> focus next
                if (content === '' || checkCaretLastLine()) {
                    const currentIndex = blocksRef.current.findIndex(b => b.id === id);
                    if (currentIndex < blocksRef.current.length - 1) {
                        e.preventDefault();

                        // Find next VISIBLE block
                        let nextVisibleIndex = currentIndex + 1;
                        while (nextVisibleIndex < blocksRef.current.length) {
                            const b = blocksRef.current[nextVisibleIndex];
                            // Check if this block is hidden by some parent toggle (including the current block if it just collapsed)
                            let isHidden = false;
                            for (let i = 0; i < nextVisibleIndex; i++) {
                                const parent = blocksRef.current[i];
                                if (parent.type === 'toggle' && parent.metadata?.isCollapsed && (b.indent || 0) > (parent.indent || 0)) {
                                    isHidden = true;
                                    break;
                                }
                            }
                            if (!isHidden) break;
                            nextVisibleIndex++;
                        }

                        if (nextVisibleIndex < blocksRef.current.length) {
                            const x = getCaretX();
                            const fallbackOffset = getCaretOffset();
                            if (x !== null) {
                                caretPositionRef.current = { x, line: 'first', fallbackOffset };
                            } else {
                                caretPositionRef.current = fallbackOffset;
                            }
                            setFocusId(blocksRef.current[nextVisibleIndex].id);
                        }
                    }
                }
            }
        } else if ((e.ctrlKey || e.metaKey) && e.key === 'a') {
            // "Select All" Logic
            // Browser default selects text in current block.
            // If we prevent default, we can select all blocks.
            // But we want "Intelligent Select All": 1st press = text, 2nd press = blocks.
            // We can check if all text is already selected?

            const selection = window.getSelection();
            // Check if current text is fully selected
            const isFullTextSelected = selection && selection.toString() === content;

            if (isFullTextSelected || content === '') {
                // Escalate to Block Selection (All Blocks)
                e.preventDefault();
                const allIds = new Set(blocksRef.current.map(b => b.id));
                setSelectedBlockIds(allIds);
                if (document.activeElement instanceof HTMLElement) document.activeElement.blur();
                editorRef.current?.focus({ preventScroll: true });
            }
            // else let browser select all text (default)
        }
        // NOTE: selection-aware Backspace/Delete is handled at the TOP of this
        // chain — branches placed here are shadowed by the single-block
        // Backspace/Delete branches above and can never execute.
    }, [handleIndent, handleOutdent, convertBlock, addBlock, removeBlock, debouncedOnUpdate]);

    const handleBlockMenuOpen = useCallback((e: React.MouseEvent, id: string) => {
        setMouseDownBlock(null);

        const target = e.target as HTMLElement;
        const isInteractive =
            target.isContentEditable ||
            target.tagName === 'INPUT' ||
            target.tagName === 'TEXTAREA';

        const isHandle = target.closest(`.${styles.dragHandle}`);

        if (isInteractive && !isHandle) {
            if (!selectedBlockIdsRef.current.has(id)) {
                if (!promoteBlockHandles) {
                    e.stopPropagation();
                }
                return;
            }
        }

        e.preventDefault();
        e.stopPropagation();

        if (!selectedBlockIdsRef.current.has(id)) {
            setSelectedBlockIds(new Set([id]));
        }

        setBlockMenuState(prev => {
            if (prev?.blockId === id) {
                // If we are toggling it off, we should ideally clear the selection. 
                // But we can't safely call setSelectedBlockIds from inside here without side-effects warning.
                // We'll just close the menu. The selection will stay unless they click away.
                // Or we can fire a timeout to clear it.
                setTimeout(() => setSelectedBlockIds(new Set()), 0);
                return null;
            }
            return { x: e.clientX, y: e.clientY, blockId: id };
        });
    }, [promoteBlockHandles, setMouseDownBlock, setSelectedBlockIds, selectedBlockIdsRef]);

    const handleRegisterRef = useCallback((id: string, el: HTMLDivElement | null) => {
        blockRefs.current[id] = el;
    }, []);

    /** The blocks currently selected, in document order. */
    const getSelectedBlocks = useCallback(
        () => blocksRef.current.filter(b => selectedBlockIdsRef.current.has(b.id)),
        [blocksRef, selectedBlockIdsRef]
    );

    /**
     * Build the clipboard flavours for a set of blocks: readable text for other
     * programs, and HTML carrying the real block data so a paste back into the
     * app restores headings, checkboxes, images and tables exactly.
     */
    const buildClipboard = useCallback((selectedBlocks: Block[]) => {
        const copy = cloneBlocks(selectedBlocks);
        return encodePayload(
            { v: 1, kind: 'blocks', blocks: copy },
            blocksToPlainText(selectedBlocks),
            blocksToHtml(selectedBlocks)
        );
    }, []);

    const handleCopySelection = useCallback(() => {
        const selectedBlocks = getSelectedBlocks();
        if (selectedBlocks.length === 0) return;
        const { text, html } = buildClipboard(selectedBlocks);
        void writeRichClipboard(text, html);
    }, [getSelectedBlocks, buildClipboard]);

    const handleCutSelection = useCallback(() => {
        const selectedBlocks = getSelectedBlocks();
        if (selectedBlocks.length === 0) return;
        const { text, html } = buildClipboard(selectedBlocks);
        void writeRichClipboard(text, html).then(() => {
            const ids = new Set(selectedBlocks.map(b => b.id));
            setBlocks(prev => {
                const remaining = prev.filter(b => !ids.has(b.id));
                // Never leave a note with no block at all — there would be
                // nowhere to put the caret afterwards.
                const next = remaining.length > 0 ? remaining : [{ id: uuidv4(), type: 'text' as const, content: '' }];
                debouncedOnUpdate(next);
                return next;
            });
            setSelectedBlockIds(new Set());
        });
    }, [getSelectedBlocks, buildClipboard, setBlocks, debouncedOnUpdate, setSelectedBlockIds]);

    /**
     * Ctrl+C / Ctrl+X over a block selection.
     *
     * Handled through the native copy/cut events rather than a keydown listener:
     * the event is the only place the browser lets a page put more than one
     * flavour on the clipboard, which is what makes a lossless paste possible.
     * With no block selection this does nothing, so ordinary text selection
     * inside a single block keeps the browser's own behaviour.
     */
    useEffect(() => {
        const hasSelection = () => selectedBlockIdsRef.current.size > 0;

        const writeToEvent = (e: ClipboardEvent) => {
            const selectedBlocks = getSelectedBlocks();
            if (selectedBlocks.length === 0 || !e.clipboardData) return false;
            const { text, html } = buildClipboard(selectedBlocks);
            e.clipboardData.setData('text/plain', text);
            e.clipboardData.setData('text/html', html);
            e.preventDefault();
            return true;
        };

        const onCopy = (e: ClipboardEvent) => {
            if (!hasSelection()) return;
            writeToEvent(e);
        };

        const onCut = (e: ClipboardEvent) => {
            if (!hasSelection()) return;
            if (!writeToEvent(e)) return;
            const ids = new Set(getSelectedBlocks().map(b => b.id));
            setBlocks(prev => {
                const remaining = prev.filter(b => !ids.has(b.id));
                const next = remaining.length > 0 ? remaining : [{ id: uuidv4(), type: 'text' as const, content: '' }];
                debouncedOnUpdate(next);
                return next;
            });
            setSelectedBlockIds(new Set());
        };

        document.addEventListener('copy', onCopy);
        document.addEventListener('cut', onCut);
        return () => {
            document.removeEventListener('copy', onCopy);
            document.removeEventListener('cut', onCut);
        };
    }, [getSelectedBlocks, buildClipboard, setBlocks, debouncedOnUpdate, setSelectedBlockIds, selectedBlockIdsRef]);

    const handleContainerPaste = async (e: React.ClipboardEvent) => {
        // Intercept paste only when not typing inside text inputs, textareas or
        // contenteditables — those have their own per-block paste handler.
        const target = e.target as HTMLElement;
        const isEditable = typeof target?.closest === 'function' && (
            target.tagName === 'INPUT' ||
            target.tagName === 'TEXTAREA' ||
            target.isContentEditable ||
            !!target.closest('[contenteditable]')
        );
        if (isEditable) return;

        let parsedBlocks: Block[] = [];
        const files = e.clipboardData.files;

        if (files && files.length > 0) {
            e.preventDefault();
            parsedBlocks = await parseFiles(files);
        } else {
            const text = e.clipboardData.getData('text/plain')?.trim();
            const html = e.clipboardData.getData('text/html');
            if (!text && !html) return;
            e.preventDefault();
            // Blocks copied from inside the app come back exactly as they were.
            const internal = payloadBlocks(decodePayload(html) ?? { v: 1, kind: 'blocks', blocks: [] });
            parsedBlocks = internal && internal.length > 0 ? internal : parseTextOrHtml(e);
        }

        if (parsedBlocks.length === 0) return;

        /* Land the paste just after whatever is selected rather than at the very
           end of the note. Appending to the end meant a paste could arrive far
           from where the user was working, out of sight. */
        const selectedIds = selectedBlockIdsRef.current;
        setBlocks(prev => {
            let insertAt = prev.length;
            if (selectedIds.size > 0) {
                const lastSelected = prev.reduce((acc, b, i) => (selectedIds.has(b.id) ? i : acc), -1);
                if (lastSelected >= 0) insertAt = lastSelected + 1;
            }
            const newBlocks = [...prev];
            newBlocks.splice(insertAt, 0, ...parsedBlocks);
            debouncedOnUpdate(newBlocks);
            return newBlocks;
        });
        setSelectedBlockIds(new Set());
        setTimeout(() => setFocusId(parsedBlocks[parsedBlocks.length - 1].id), 50);
    };

    return (
        <div
            data-chnk-it-block-editor
            className={`${styles.editor} ${minimal ? styles.minimal : ''}`}
            ref={editorRef}
            tabIndex={-1}
            onBlurCapture={(event) => {
                const nextTarget = event.relatedTarget as Node | null;
                if (!nextTarget || !editorRef.current?.contains(nextTarget)) {
                    flushPendingUpdate();
                }
            }}
            onPaste={handleContainerPaste}
            onDrop={(e) => { handleDrop(e); clearBlockDropIndicators(); }}
            onDragOver={handleEditorDragOver}
            onDragLeave={handleEditorDragLeave}
            onClick={(e) => handleEditorClick(e, wasDraggingRef.current)}
            onPointerDown={(e) => {
                if (e.ctrlKey) {
                    e.stopPropagation();
                }
            }}
            onMouseDown={(e) => {
                // Require Ctrl key for bulk selection
                if (!e.ctrlKey) {
                    return;
                }
                e.stopPropagation(); // Stop React Flow from grabbing the event for canvas selection
                if (e.button === 0 && editorRef.current) {
                    wasDraggingRef.current = false;
                    // Start Selection
                    const rect = editorRef.current.getBoundingClientRect();
                    // Calculate Scale (Robust check for width)
                    const scale = rect.width ? (rect.width / editorRef.current.offsetWidth) : 1;

                    const relativeX = (e.clientX - rect.left) / scale;
                    const relativeY = (e.clientY - rect.top) / scale;

                    setDragSelection({
                        startX: relativeX,
                        startY: relativeY,
                        currentX: relativeX,
                        currentY: relativeY
                    });

                    // Clear previous if not purely additive (Ctrl allows adding, but let's keep it simple: simple click clears)
                    if (!e.shiftKey && !e.ctrlKey) {
                        setSelectedBlockIds(new Set());
                    }
                }
            }}
            onDoubleClick={(e) => {
                const target = e.target as HTMLElement;
                const chip = target.closest(`.${styles.inlinePageChip}`) as HTMLElement;
                if (chip && chip.dataset.nodeId) {
                    e.preventDefault();
                    e.stopPropagation();
                    const nodeId = chip.dataset.nodeId;
                    useStore.getState().navigateToNode(nodeId);
                }
            }}
        >
            {(() => {
                const visibleBlocks: { block: Block, listIndex?: number, hasChildren?: boolean, originalIndex: number }[] = [];

                blocks.forEach((block, index) => {
                    // Calculate List Index for numbered blocks
                    let listIndex = undefined;
                    if (block.type === 'numbered') {
                        let count = index === 0 ? globalStartIndex : 1;
                        if (index > 0) {
                            for (let i = index - 1; i >= 0; i--) {
                                if (blocks[i].type === 'numbered' && (blocks[i].indent || 0) === (block.indent || 0)) {
                                    count++;
                                } else if ((blocks[i].indent || 0) < (block.indent || 0)) {
                                    break;
                                } else if (blocks[i].type !== 'numbered' && (blocks[i].indent || 0) === (block.indent || 0)) {
                                    break; // Reset list if interrupted by another block type at same indent
                                }
                            }
                        }
                        listIndex = count;
                    }

                    // If this block is a toggle, calculate hasChildren
                    let hasChildren = false;
                    if (block.type === 'toggle') {
                        // Check if the next block in the flat list is indented relative to this one
                        if (index < blocks.length - 1 && (blocks[index + 1].indent || 0) > (block.indent || 0)) {
                            hasChildren = true;
                        }
                    }

                    visibleBlocks.push({ block, listIndex, hasChildren, originalIndex: index });
                });

                interface RenderNode {
                    type: 'block' | 'toggle-group';
                    block: Block;
                    listIndex?: number;
                    hasChildren?: boolean;
                    originalIndex: number;
                    children: RenderNode[];
                }

                const buildRenderTree = (blocksList: typeof visibleBlocks): RenderNode[] => {
                    const root: RenderNode[] = [];
                    const stack: { node: RenderNode; indent: number }[] = [];

                    blocksList.forEach(item => {
                        const indent = item.block.indent || 0;

                        // Find the correct parent in the stack
                        while (stack.length > 0 && stack[stack.length - 1].indent >= indent) {
                            stack.pop();
                        }

                        const currentNode: RenderNode = {
                            type: item.block.type === 'toggle' ? 'toggle-group' : 'block',
                            block: item.block,
                            listIndex: item.listIndex,
                            hasChildren: item.hasChildren,
                            originalIndex: item.originalIndex,
                            children: []
                        };

                        if (stack.length > 0) {
                            stack[stack.length - 1].node.children.push(currentNode);
                        } else {
                            root.push(currentNode);
                        }

                        if (item.block.type === 'toggle') {
                            stack.push({ node: currentNode, indent });
                        }
                    });

                    return root;
                };

                const renderNode = (node: RenderNode, parentToggleIndent?: number, forceReadOnly?: boolean, isFirstChildOfToggle?: boolean): React.ReactNode => {
                    const currentReadOnly = readOnly || forceReadOnly;
                    if (node.type === 'block') {
                        return (
                            <React.Fragment key={node.block.id}>
                                <BlockItem
                                    block={node.block}
                                    index={node.listIndex}
                                    hasChildren={node.hasChildren}
                                    useStoredListNumber={useStoredListNumbers}
                                    isSelected={selectedBlockIds.has(node.block.id)}
                                    isFirstChildOfToggle={isFirstChildOfToggle}
                                    readOnly={currentReadOnly}
                                    nodeId={nodeId}
                                    hideBlockHandles={hideBlockHandles}
                                    promoteBlockHandles={promoteBlockHandles}
                                    disableMediaControls={disableMediaControls}
                                    parentToggleIndent={parentToggleIndent}
                                    minimal={minimal}
                                    onUpdateBlock={updateBlock}
                                    onKeyDown={handleKeyDown}
                                    onPaste={handleBlockPaste}
                                    onMoveBlock={handleMoveBlock}
                                    onDragStart={handleDragStartWrapped}
                                    onMenuOpen={handleBlockMenuOpen}
                                    onDeleteBlock={handleDeleteBlock}
                                    onSelectionClick={() => {
                                        if (selectedBlockIds.size > 0) {
                                            setSelectedBlockIds(new Set());
                                        }
                                    }}
                                    onSelectionMouseDown={handleSelectionMouseDown}
                                    onRegisterRef={handleRegisterRef}
                                />
                                {renderBetweenBlocks && node.originalIndex < blocks.length - 1 && renderBetweenBlocks(node.originalIndex)}
                            </React.Fragment>
                        );
                    } else {
                        const showChildren = node.children && node.children.length > 0;
                        const relativeIndent = Math.max(0, (node.block.indent || 0) - (parentToggleIndent || 0));
                        const isCollapsed = node.block.metadata?.isCollapsed;
                        return (
                            <React.Fragment key={node.block.id}>
                                <div
                                    className={styles.toggleGroupContainer}
                                    // Published as a variable, not an inline margin-left: as an
                                    // inline style it beat every stylesheet rule and flattened the
                                    // canvas gutter to 0 on the left (same trap as --block-indent).
                                    style={{ '--toggle-indent': `${relativeIndent * 24}px` } as React.CSSProperties}
                                >
                                    <BlockItem
                                        block={node.block}
                                        index={node.listIndex}
                                        hasChildren={node.hasChildren}
                                        useStoredListNumber={useStoredListNumbers}
                                        isSelected={selectedBlockIds.has(node.block.id)}
                                        readOnly={currentReadOnly}
                                        nodeId={nodeId}
                                        hideBlockHandles={hideBlockHandles}
                                        promoteBlockHandles={promoteBlockHandles}
                                        disableMediaControls={disableMediaControls}
                                        parentToggleIndent={node.block.indent || 0}
                                        minimal={minimal}
                                        onUpdateBlock={updateBlock}
                                        onKeyDown={handleKeyDown}
                                        onPaste={handleBlockPaste}
                                        onMoveBlock={handleMoveBlock}
                                        onDragStart={handleDragStartWrapped}
                                        onMenuOpen={handleBlockMenuOpen}
                                        onDeleteBlock={handleDeleteBlock}
                                        onSelectionClick={() => {
                                            if (selectedBlockIds.size > 0) {
                                                setSelectedBlockIds(new Set());
                                            }
                                        }}
                                        onSelectionMouseDown={handleSelectionMouseDown}
                                        onRegisterRef={handleRegisterRef}
                                    />
                                    {showChildren && !isCollapsed && (
                                        <div className={styles.toggleChildrenContainer}>
                                            {node.children.map((child, i) => renderNode(child, node.block.indent || 0, currentReadOnly, i === 0))}
                                        </div>
                                    )}
                                </div>
                                {renderBetweenBlocks && node.originalIndex < blocks.length - 1 && renderBetweenBlocks(node.originalIndex)}
                            </React.Fragment>
                        );
                    }
                };

                const renderTree = buildRenderTree(visibleBlocks);
                return renderTree.map(node => renderNode(node));
            })()}

            {slashMenuState && (
                <SlashMenu
                    anchorRect={slashMenuState.anchorRect}
                    filter={blocksRef.current.find(b => b.id === slashMenuState.blockId)?.content.substring(1) || ''}
                    onSelect={(type, meta) => convertBlock(undefined, type, meta, '')}
                    onClose={() => {
                        const targetId = slashMenuState.blockId;
                        setSlashMenuState(null);
                        setFocusId(targetId);
                    }}
                    nodeColor={nodeColor}
                    theme={theme}
                />
            )}

            {blockMenuState && (
                <BlockMenu
                    x={blockMenuState.x}
                    y={blockMenuState.y}
                    // blockId={blockMenuState.blockId} // Passed via closure/state to onAction
                    currentType={blocks.find(b => b.id === blockMenuState.blockId)?.type || 'text'}
                    onClose={() => {
                        const targetId = blockMenuState.blockId;
                        setBlockMenuState(prev => {
                            if (prev?.blockId === targetId) {
                                return null;
                            }
                            return prev;
                        });
                    }}
                    onAction={(action, value) => handleBlockMenuAction(blockMenuState.blockId, action, value)}
                />
            )}
            {/* Floating Toolbar */}
            {/* selectionRect goes null the moment the DOM selection collapses,
                which a click on the toolbar itself can do — so a row the user is
                still working in (the link field, the palette) keeps the toolbar
                mounted against the last known rect. */}
            {(selectionRect || ((linkPopoverOpen || colorPopoverOpen) && lastSelectionRect)) && !slashMenuState && !blockMenuState && (
                <FloatingToolbar
                    selectionRect={(selectionRect || lastSelectionRect)!}
                    activeFormats={activeFormats}
                    activeHighlight={activeHighlight}
                    initialLinkUrl={activeLinkUrl}
                    linkOpen={linkPopoverOpen}
                    onLinkOpenChange={(open) => {
                        setLinkPopoverOpen(open);
                        if (open) setColorPopoverOpen(false);   // one row at a time
                    }}
                    colorOpen={colorPopoverOpen}
                    onColorOpenChange={(open) => {
                        setColorPopoverOpen(open);
                        if (open) setLinkPopoverOpen(false);
                    }}
                    onFormat={(format, value) => {
                        if (format === 'createLink') {
                            if (value !== undefined) applyLink(value);
                        } else if (format === 'createPage') {
                            createPageChip();
                        } else if (format === 'highlight') {
                            // No value = clear it; the swatches always send a hue.
                            highlightSelection(isHighlightHue(value) ? value : null);
                        } else {
                            formatSelection(format as InlineFormat);
                        }
                    }}
                />
            )}

            {/* Selection Rect Overlay */}
            {dragSelection && selectedBlockIds.size > 1 && (
                <div
                    className={styles.selectionRect}
                    style={{
                        left: Math.min(dragSelection.startX, dragSelection.currentX),
                        top: Math.min(dragSelection.startY, dragSelection.currentY),
                        width: Math.abs(dragSelection.currentX - dragSelection.startX),
                        height: Math.abs(dragSelection.currentY - dragSelection.startY)
                    }}
                />
            )}

            {/* Selection Counter */}
            {/* Selection Capsule (Dynamic Island) */}
            {selectedBlockIds.size > 1 && selectionIslandPortalId && (() => {
                const portalTarget = document.getElementById(selectionIslandPortalId);
                if (!portalTarget) return null;
                return createPortal(
                    <SelectionCapsule
                        count={selectedBlockIds.size}
                        onClear={() => setSelectedBlockIds(new Set())}
                        onDelete={deleteSelectedBlocks}
                        onCopy={handleCopySelection}
                        onCut={handleCutSelection}
                    />,
                    portalTarget
                );
            })()}

            {/* Fallback for non-portal mode */}
            {selectedBlockIds.size > 1 && !selectionIslandPortalId && (
                <SelectionCapsule
                    count={selectedBlockIds.size}
                    onClear={() => setSelectedBlockIds(new Set())}
                    onDelete={deleteSelectedBlocks}
                    onCopy={handleCopySelection}
                    onCut={handleCutSelection}
                />
            )}
        </div>
    );
});

import { useRef, useEffect, useState, useLayoutEffect } from 'react';
import { createPortal } from 'react-dom';
import { Trash2, Copy, Type, Palette, ArrowRight, Heading1, Heading2, Heading3, CheckSquare, Quote, List, ListOrdered, Code, Link, ChevronDown } from '../../components/icons';
import styles from './BlockEditor.module.css';
import type { BlockType } from './types';
import { Tabs, type TabItem } from '../../components/ui/Tabs';

type ColorTab = 'text' | 'background';

const COLOR_TABS: TabItem<ColorTab>[] = [
    { id: 'text', label: 'Text' },
    { id: 'background', label: 'Background' },
];

type BlockMenuActionValue = BlockType | { type: 'text' | 'background'; value: string } | number;

interface BlockMenuProps {
    x: number;
    y: number;
    // blockId: string; // Not needed
    currentType: BlockType;
    onClose: () => void;
    onAction: (action: 'turnInto' | 'color' | 'duplicate' | 'delete' | 'split' | 'toggleHeader', value?: BlockMenuActionValue) => void;
}

const TURN_INTO_ITEMS: { label: string; type: BlockType; icon: React.ReactNode }[] = [
    { label: 'Text', type: 'text', icon: <Type size={16} /> },
    { label: 'Heading 1', type: 'heading1', icon: <Heading1 size={16} /> },
    { label: 'Heading 2', type: 'heading2', icon: <Heading2 size={16} /> },
    { label: 'Heading 3', type: 'heading3', icon: <Heading3 size={16} /> },
    { label: 'Bulleted List', type: 'bullet', icon: <List size={16} /> },
    { label: 'Numbered List', type: 'numbered', icon: <ListOrdered size={16} /> },
    { label: 'To-do', type: 'todo', icon: <CheckSquare size={16} /> },
    { label: 'Quote', type: 'quote', icon: <Quote size={16} /> },
    { label: 'Code', type: 'code', icon: <Code size={16} /> },
    { label: 'Smart Link', type: 'link', icon: <Link size={16} /> },
    { label: 'Color Block', type: 'color', icon: <Palette size={16} /> },
];

const COLORS = [
    { label: 'Default', value: 'inherit' },
    { label: 'Gray', value: '#787774' },
    { label: 'Brown', value: '#9f6b53' },
    { label: 'Orange', value: '#d9730d' },
    { label: 'Yellow', value: '#cb912f' },
    { label: 'Green', value: '#448361' },
    { label: 'Coral', value: '#ff5040' },
    { label: 'Purple', value: '#9065b0' },
    { label: 'Pink', value: '#c14c8a' },
    { label: 'Red', value: '#d44c47' },
];

export function BlockMenu({ x, y, currentType, onClose, onAction }: BlockMenuProps) {
    const menuRef = useRef<HTMLDivElement>(null);
    const [activeSubMenu, setActiveSubMenu] = useState<'turnInto' | 'color' | null>(null);
    const [colorTab, setColorTab] = useState<ColorTab>('text');
    const [positionedCoords, setPositionedCoords] = useState<{ x: number; y: number } | null>(null);

    useLayoutEffect(() => {
        if (!menuRef.current) return;

        const menuWidth = menuRef.current.offsetWidth || 270;
        const menuHeight = menuRef.current.offsetHeight || 300;

        const viewportWidth = window.innerWidth;
        const viewportHeight = window.innerHeight;

        // Dynamic vertical (y) positioning
        let finalY = y;
        if (y > viewportHeight / 2) {
            // Mouse is in the bottom half: open on top of the mouse
            finalY = y - menuHeight - 8;
        } else {
            // Mouse is in the top half: open under the mouse
            finalY = y + 8;
        }

        // Dynamic horizontal (x) positioning
        // Avoid overlapping the block (which is on the right of the handle).
        // Try to open to the left of the handle click.
        let finalX = x - menuWidth - 8;
        if (finalX < 8) {
            // Not enough space on the left: open to the right of the handle click
            finalX = Math.min(x + 16, viewportWidth - menuWidth - 8);
        }

        // Constrain coords to keep the menu fully within the viewport bounds
        finalY = Math.max(8, Math.min(finalY, viewportHeight - menuHeight - 8));
        finalX = Math.max(8, Math.min(finalX, viewportWidth - menuWidth - 8));

        setPositionedCoords({ x: finalX, y: finalY });
    }, [x, y]);

    // Close on click outside or Esc key
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
                setTimeout(onClose, 0);
            }
        };
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                onClose();
            }
        };
        document.addEventListener('mousedown', handleClickOutside, { capture: true });
        document.addEventListener('keydown', handleKeyDown, { capture: true });
        return () => {
            document.removeEventListener('mousedown', handleClickOutside, { capture: true });
            document.removeEventListener('keydown', handleKeyDown, { capture: true });
        };
    }, [onClose]);

    const handleMainAction = (action: 'duplicate' | 'delete' | 'split') => {
        onAction(action);
        onClose();
    };

    // Submenu Rendering Helper
    const renderSubMenu = () => {
        if (!activeSubMenu) return null;

        // Position relative to parent menu width (approx 220px)
        const subMenuStyle: React.CSSProperties = {
            position: 'absolute',
            top: 0,
            left: '100%',
            marginLeft: '4px', // Gap
            width: '200px',
            maxHeight: '300px',
            overflowY: 'auto'
        };

        return (
            <div className={`${styles.slashMenu} block-menu`} role="menu" style={subMenuStyle}>
                {activeSubMenu === 'turnInto' && (
                    <>
                        <div className={styles.menuHeader}>Turn into</div>
                        {TURN_INTO_ITEMS.map(item => (
                            <div
                                key={item.type}
                                className={`${styles.slashMenuItem} ${currentType === item.type ? styles.selected : ''}`}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    onAction('turnInto', item.type);
                                    onClose();
                                }}
                            >
                                <span className={styles.slashIcon}>{item.icon}</span>
                                <span className={styles.slashLabel}>{item.label}</span>
                            </div>
                        ))}
                    </>
                )}

                {activeSubMenu === 'color' && (
                    <>
                        {/* The menu closes on any click that reaches it, so the
                            strip is wrapped in its own stopPropagation rather
                            than each tab carrying one. */}
                        <div
                            className={styles.tabContainer}
                            onClick={(e) => e.stopPropagation()}
                        >
                            <Tabs
                                items={COLOR_TABS}
                                value={colorTab}
                                onChange={setColorTab}
                                size="sm"
                                color="accent"
                                radius="control"
                                fullWidth
                                aria-label="Colour target"
                            />
                        </div>
                        <div className={styles.menuHeader} style={{ marginTop: 0 }}>{colorTab === 'text' ? 'Text Color' : 'Background'}</div>
                        {COLORS.map(item => (
                            <div
                                key={`${colorTab}-${item.value}`}
                                className={styles.slashMenuItem}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    if (colorTab === 'text') {
                                        onAction('color', { type: 'text', value: item.value });
                                    } else {
                                        const val = item.value === 'inherit' ? 'transparent' : `${item.value}20`;
                                        onAction('color', { type: 'background', value: val });
                                    }
                                    onClose();
                                }}
                            >
                                <span className={styles.slashIcon} style={
                                    colorTab === 'text' ? {
                                        color: item.value === 'inherit' ? 'var(--color-text-main)' : item.value
                                    } : {
                                        background: item.value === 'inherit' ? 'transparent' : item.value,
                                        border: item.value === 'inherit' ? '1px solid #555' : 'none'
                                    }
                                }>
                                    {colorTab === 'text' ? (
                                        <>
                                            <div style={{ width: 12, height: 12, borderRadius: '2px', background: 'currentColor' }} />
                                            <span style={{ marginLeft: 6 }}>A</span>
                                        </>
                                    ) : (
                                        <div style={{ width: '100%', height: '100%' }} />
                                    )}
                                </span>
                                <span className={styles.slashLabel}>{item.label}</span>
                            </div>
                        ))}
                    </>
                )}
            </div>
        );
    };

    return createPortal(
        <div
            className={`${styles.slashMenu} block-menu`}
            role="menu"
            style={{
                top: positionedCoords ? positionedCoords.y : y,
                left: positionedCoords ? positionedCoords.x : x,
                visibility: positionedCoords ? 'visible' : 'hidden',
                opacity: positionedCoords ? 1 : 0,
                overflow: 'visible',
                transform: positionedCoords ? 'scale(1)' : 'scale(0.95)',
                transition: 'opacity 0.12s cubic-bezier(0.16, 1, 0.3, 1), transform 0.12s cubic-bezier(0.16, 1, 0.3, 1)',
            }} // Allow submenu to overflow, measure off-screen/invisible initially
            ref={menuRef}
            onMouseDown={(e) => e.stopPropagation()}
        >
            <div className={styles.menuHeader}>Actions</div>

            <div className={styles.slashMenuItem} onMouseEnter={() => setActiveSubMenu(null)} onClick={(e) => { e.stopPropagation(); handleMainAction('duplicate'); }}>
                <span className={styles.slashIcon}><Copy size={16} /></span>
                <span className={styles.slashLabel}>Duplicate</span>
            </div>

            <div className={`${styles.slashMenuItem} ${styles.dangerItem}`} onMouseEnter={() => setActiveSubMenu(null)} onClick={(e) => { e.stopPropagation(); handleMainAction('delete'); }}>
                <span className={styles.slashIcon}><Trash2 size={16} /></span>
                <span className={styles.slashLabel}>Delete</span>
            </div>

            <div className={styles.divider} />

            <div className={styles.slashMenuItem} onMouseEnter={() => setActiveSubMenu(null)} onClick={(e) => { e.stopPropagation(); handleMainAction('split'); }}>
                <span className={styles.slashIcon}><ArrowRight size={16} /></span>
                <span className={styles.slashLabel}>Split Note Here</span>
            </div>

            {(currentType === 'heading1' || currentType === 'heading2' || currentType === 'heading3') && (
                <div className={styles.slashMenuItem} onMouseEnter={() => setActiveSubMenu(null)} onClick={(e) => { e.stopPropagation(); onAction('toggleHeader'); onClose(); }}>
                    <span className={styles.slashIcon}><ChevronDown size={16} /></span>
                    <span className={styles.slashLabel}>Toggle Header</span>
                </div>
            )}

            <div className={styles.divider} />

            <div
                className={styles.slashMenuItem}
                onMouseEnter={() => setActiveSubMenu('turnInto')}
                style={activeSubMenu === 'turnInto' ? { background: 'var(--menu-item-active)' } : {}} // Highlight parent
            >
                <span className={styles.slashIcon}><ArrowRight size={16} /></span>
                <span className={styles.slashLabel} style={{ flexGrow: 1 }}>Turn into</span>
                <span className={styles.menuArrow}>›</span>
            </div>

            <div
                className={styles.slashMenuItem}
                onMouseEnter={() => setActiveSubMenu('color')}
                style={activeSubMenu === 'color' ? { background: 'var(--menu-item-active)' } : {}} // Highlight parent
            >
                <span className={styles.slashIcon}><Palette size={16} /></span>
                <span className={styles.slashLabel} style={{ flexGrow: 1 }}>Color</span>
                <span className={styles.menuArrow}>›</span>
            </div>

            {/* Render Submenu Side-by-Side */}
            {renderSubMenu()}
        </div>,
        document.body
    );
}

import { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { HexColorPicker } from 'react-colorful';
import { Copy, Check, X } from '../../components/icons';
import editorStyles from './BlockEditor.module.css';
import modalStyles from './ColorBlockModal.module.css';
import type { BlockMetadata } from './types';
import { getNearestColorName, normalizeHex, hexToRgb, rgbToHex, rgbToRgbaString, rgbToHslString } from './colorUtils';

function HexInput({ color, onChange }: { color: string; onChange: (c: string) => void }) {
    const [input, setInput] = useState(color);

    useEffect(() => {
        setInput(color);
    }, [color]);

    const handleChange = (val: string) => {
        setInput(val);
        const normalized = normalizeHex(val);
        if (/^#[0-9A-F]{6}$/i.test(normalized)) {
            onChange(normalized);
        }
    };

    return (
        <div className={editorStyles.colorInputGroup}>
            <input className={editorStyles.colorInput} value={input} onChange={(e) => handleChange(e.target.value)} />
            <span className={editorStyles.colorInputLabel}>HEX</span>
        </div>
    );
}

function HslInput({ color, onChange }: { color: string; onChange: (c: string) => void }) {
    const rgb = hexToRgb(color);
    const r = rgb.r / 255;
    const g = rgb.g / 255;
    const b = rgb.b / 255;
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    const delta = max - min;

    let h = 0;
    if (delta) {
        if (max === r) h = ((g - b) / delta) % 6;
        else if (max === g) h = (b - r) / delta + 2;
        else h = (r - g) / delta + 4;
    }
    h = Math.round(h * 60);
    if (h < 0) h += 360;

    const l = (max + min) / 2;
    const s = delta === 0 ? 0 : delta / (1 - Math.abs(2 * l - 1));

    const handleChange = (part: 'h' | 's' | 'l', val: string) => {
        let v = parseInt(val);
        if (isNaN(v)) v = 0;
        const h_val = part === 'h' ? Math.max(0, Math.min(360, v)) : h;
        const s_val = part === 's' ? Math.max(0, Math.min(100, v)) : Math.round(s * 100);
        const l_val = part === 'l' ? Math.max(0, Math.min(100, v)) : Math.round(l * 100);

        const hslToRgb = (h: number, s: number, l: number) => {
            s /= 100;
            l /= 100;
            const k = (n: number) => (n + h / 30) % 12;
            const a = s * Math.min(l, 1 - l);
            const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
            return {
                r: Math.round(255 * f(0)),
                g: Math.round(255 * f(8)),
                b: Math.round(255 * f(4))
            };
        };

        const newRgb = hslToRgb(h_val, s_val, l_val);
        onChange(rgbToHex(newRgb.r, newRgb.g, newRgb.b));
    };

    return (
        <div className={editorStyles.colorInputRow}>
            <div className={editorStyles.colorInputGroup}>
                <input className={editorStyles.colorInput} value={h} onChange={(e) => handleChange('h', e.target.value)} />
                <span className={editorStyles.colorInputLabel}>H</span>
            </div>
            <div className={editorStyles.colorInputGroup}>
                <input className={editorStyles.colorInput} value={Math.round(s * 100)} onChange={(e) => handleChange('s', e.target.value)} />
                <span className={editorStyles.colorInputLabel}>S</span>
            </div>
            <div className={editorStyles.colorInputGroup}>
                <input className={editorStyles.colorInput} value={Math.round(l * 100)} onChange={(e) => handleChange('l', e.target.value)} />
                <span className={editorStyles.colorInputLabel}>L</span>
            </div>
        </div>
    );
}

function RgbInput({ color, onChange }: { color: string; onChange: (c: string) => void }) {
    const rgb = hexToRgb(color);

    const handleChange = (part: 'r' | 'g' | 'b', val: string) => {
        let v = parseInt(val);
        if (isNaN(v)) v = 0;
        if (v < 0) v = 0;
        if (v > 255) v = 255;
        const newRgb = { ...rgb, [part]: v };
        onChange(rgbToHex(newRgb.r, newRgb.g, newRgb.b));
    };

    return (
        <div className={editorStyles.colorInputRow}>
            <div className={editorStyles.colorInputGroup}>
                <input className={editorStyles.colorInput} value={rgb.r} onChange={(e) => handleChange('r', e.target.value)} />
                <span className={editorStyles.colorInputLabel}>R</span>
            </div>
            <div className={editorStyles.colorInputGroup}>
                <input className={editorStyles.colorInput} value={rgb.g} onChange={(e) => handleChange('g', e.target.value)} />
                <span className={editorStyles.colorInputLabel}>G</span>
            </div>
            <div className={editorStyles.colorInputGroup}>
                <input className={editorStyles.colorInput} value={rgb.b} onChange={(e) => handleChange('b', e.target.value)} />
                <span className={editorStyles.colorInputLabel}>B</span>
            </div>
        </div>
    );
}

interface ColorBlockModalProps {
    color: string;
    originalColor?: string;
    metadata?: BlockMetadata;
    displayName?: string;
    onChange: (content: string, metadata?: BlockMetadata) => void;
    onClose: () => void;
}

export function ColorBlockModal({ color, originalColor, metadata, displayName: initialName, onChange, onClose }: ColorBlockModalProps) {
    const [currentColor, setCurrentColor] = useState(color);
    // Lock the original color at the time the modal first opened
    const lockedOriginal = useRef(originalColor || color);
    const [copiedKey, setCopiedKey] = useState<'hex' | 'rgba' | 'hsl' | null>(null);
    const [inputMode, setInputMode] = useState<'hex' | 'rgb' | 'hsl'>('hex');
    const [name, setName] = useState(metadata?.name || initialName || getNearestColorName(color));
    const overlayRef = useRef<HTMLDivElement>(null);
    const currentColorRef = useRef(color);

    const [recentColors] = useState<string[]>(() => {
        try {
            const saved = localStorage.getItem('chnk-it-recent-colors');
            return saved ? JSON.parse(saved) : [];
        } catch {
            return [];
        }
    });

    const normalizedHex = normalizeHex(currentColor);
    const rgb = hexToRgb(normalizedHex);
    const rgbaValue = rgbToRgbaString(rgb, 1);
    const hslValue = rgbToHslString(rgb);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                e.stopPropagation();
                onClose();
            }
        };
        // Use capture: true so we intercept Escape before CanvasBoard stops propagation
        window.addEventListener('keydown', handleKeyDown, { capture: true });
        return () => {
            window.removeEventListener('keydown', handleKeyDown, { capture: true });
            
            // Save final color to recents on unmount
            const finalColor = normalizeHex(currentColorRef.current);
            try {
                const saved = localStorage.getItem('chnk-it-recent-colors');
                let recents = saved ? JSON.parse(saved) : [];
                // Remove if exists, then unshift to front
                recents = recents.filter((c: string) => c !== finalColor);
                recents.unshift(finalColor);
                if (recents.length > 10) recents = recents.slice(0, 10);
                localStorage.setItem('chnk-it-recent-colors', JSON.stringify(recents));
            } catch (e) {
                console.warn('Failed to save recent colors', e);
            }
        };
    }, [onClose]);

    const handleOverlayClick = (e: React.MouseEvent) => {
        if (e.target === overlayRef.current) onClose();
    };

    const handleColorPickerChange = (newColor: string) => {
        setCurrentColor(newColor);
        currentColorRef.current = newColor;
        const newName = getNearestColorName(newColor);
        setName(newName);
        onChange(newColor, { ...metadata, name: newName });
    };

    const handleNameBlur = () => {
        onChange(currentColor, { ...metadata, name });
    };

    const handleCopyValue = (value: string, key: 'hex' | 'rgba' | 'hsl') => (e: React.MouseEvent) => {
        e.stopPropagation();
        navigator.clipboard.writeText(value);
        setCopiedKey(key);
        setTimeout(() => setCopiedKey(null), 2000);
    };

    return createPortal(
        <div className={modalStyles.overlay} ref={overlayRef} onClick={handleOverlayClick}>
            <div className={modalStyles.modal} onClick={(e) => e.stopPropagation()}>
                <div className={modalStyles.modalHeader}>
                    <input
                        className={modalStyles.modalTitle}
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        onBlur={handleNameBlur}
                        placeholder="Color name"
                    />
                    <button className={`${modalStyles.closeBtn} icon-hover`} onClick={onClose}>
                        <X size={20} />
                    </button>
                </div>

                <div className={modalStyles.pickerSection}>
                    {/* Before / After swatches */}
                    <div style={{ display: 'flex', gap: 10, marginBottom: 12, alignItems: 'center' }}>
                        <div style={{ flex: 1 }}>
                            <div style={{ fontSize: '0.68rem', color: 'var(--color-text-muted, #888)', marginBottom: 4, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Original</div>
                            <div
                                title={lockedOriginal.current}
                                style={{
                                    width: '100%',
                                    height: 36,
                                    borderRadius: 8,
                                    backgroundColor: lockedOriginal.current,
                                    border: '1.5px solid rgba(255,255,255,0.15)',
                                    boxShadow: '0 2px 6px rgba(0,0,0,0.18)',
                                }}
                            />
                        </div>
                        <div style={{ color: 'var(--color-text-muted, #888)', fontSize: '1rem', marginTop: 16 }}>→</div>
                        <div style={{ flex: 1 }}>
                            <div style={{ fontSize: '0.68rem', color: 'var(--color-text-muted, #888)', marginBottom: 4, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Current</div>
                            <div
                                title={currentColor}
                                style={{
                                    width: '100%',
                                    height: 36,
                                    borderRadius: 8,
                                    backgroundColor: currentColor,
                                    border: '1.5px solid rgba(255,255,255,0.15)',
                                    boxShadow: '0 2px 6px rgba(0,0,0,0.18)',
                                    transition: 'background-color 0.15s ease',
                                }}
                            />
                        </div>
                    </div>
                    <HexColorPicker color={currentColor} onChange={handleColorPickerChange} />
                    
                    {/* Recent Colors */}
                    {recentColors.length > 0 && (
                        <div style={{ marginTop: 16 }}>
                            <div style={{ fontSize: '0.68rem', color: 'var(--color-text-muted, #888)', marginBottom: 8, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Recent Colors</div>
                            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                                {recentColors.map(c => (
                                    <button
                                        key={c}
                                        onClick={() => handleColorPickerChange(c)}
                                        title={c}
                                        style={{
                                            width: 24,
                                            height: 24,
                                            borderRadius: '50%',
                                            backgroundColor: c,
                                            border: '1px solid rgba(255,255,255,0.15)',
                                            cursor: 'pointer',
                                            padding: 0,
                                            transition: 'transform 0.1s',
                                        }}
                                        onMouseEnter={(e) => (e.currentTarget.style.transform = 'scale(1.1)')}
                                        onMouseLeave={(e) => (e.currentTarget.style.transform = 'scale(1)')}
                                    />
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                <div className={modalStyles.bodySection}>
                    <select className={editorStyles.colorInputModeSelect} value={inputMode} onChange={(e) => setInputMode(e.target.value as 'hex' | 'rgb' | 'hsl')}>
                        <option value="hex">HEX</option>
                        <option value="rgb">RGB</option>
                        <option value="hsl">HSL</option>
                    </select>
                    <div style={{ marginTop: 12 }}>
                        {inputMode === 'hex' && <HexInput color={normalizedHex} onChange={handleColorPickerChange} />}
                        {inputMode === 'rgb' && <RgbInput color={normalizedHex} onChange={handleColorPickerChange} />}
                        {inputMode === 'hsl' && <HslInput color={normalizedHex} onChange={handleColorPickerChange} />}
                    </div>
                </div>

                <div className={modalStyles.footerSection}>
                    <div className={editorStyles.colorCodeGroup}>
                        <button type="button" className={editorStyles.colorCodeButton} onClick={handleCopyValue(normalizedHex, 'hex')}>
                            <span className={editorStyles.colorCodeLabel}>HEX</span>
                            <span className={editorStyles.colorCodeValueRow}>
                                <span className={editorStyles.colorCodeValue}>{normalizedHex}</span>
                                {copiedKey === 'hex' ? <Check size={14} className={editorStyles.colorCodeIconActive} /> : <Copy size={14} className={editorStyles.colorCodeIcon} />}
                            </span>
                        </button>
                        <button type="button" className={editorStyles.colorCodeButton} onClick={handleCopyValue(rgbaValue, 'rgba')}>
                            <span className={editorStyles.colorCodeLabel}>RGBA</span>
                            <span className={editorStyles.colorCodeValueRow}>
                                <span className={editorStyles.colorCodeValue}>{rgbaValue}</span>
                                {copiedKey === 'rgba' ? <Check size={14} className={editorStyles.colorCodeIconActive} /> : <Copy size={14} className={editorStyles.colorCodeIcon} />}
                            </span>
                        </button>
                        <button type="button" className={editorStyles.colorCodeButton} onClick={handleCopyValue(hslValue, 'hsl')}>
                            <span className={editorStyles.colorCodeLabel}>HSL</span>
                            <span className={editorStyles.colorCodeValueRow}>
                                <span className={editorStyles.colorCodeValue}>{hslValue}</span>
                                {copiedKey === 'hsl' ? <Check size={14} className={editorStyles.colorCodeIconActive} /> : <Copy size={14} className={editorStyles.colorCodeIcon} />}
                            </span>
                        </button>
                    </div>
                </div>
            </div>
        </div>,
        document.body
    );
}

