import { useEffect, useState, useMemo, useRef, useCallback, memo } from 'react';
import { useStore } from '../../store/useStore';
import styles from './BottomMenu.module.css';
import { FileText, Cuboid, KanbanSquare, ChevronRight, Hash, Clock, LayoutGrid, Search, CornerDownRight } from '../../components/icons';
import { highlightMatch, parseSearchQuery } from './searchUtils';
import type { RichSearchResult } from './searchUtils';

interface SearchResultsProps {
    query: string;
    onClose: () => void;
}

interface GroupedResults {
    label: string;
    type: string;
    icon: typeof FileText;
    results: RichSearchResult[];
}

function formatDate(dateStr?: string): string {
    if (!dateStr) return '';
    const d = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - d.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function getScoreWidth(score: number, maxScore: number): number {
    if (maxScore === 0) return 0;
    return Math.round((score / maxScore) * 100);
}

function getTypeIcon(type: string) {
    switch (type) {
        case 'note': return FileText;
        case 'kanban': return KanbanSquare;
        case 'block':
        case 'fused-note': return Cuboid;
        default: return LayoutGrid;
    }
}

function getTypeLabel(type: string): string {
    switch (type) {
        case 'note': return 'Notes';
        case 'kanban': return 'Boards';
        case 'block': return 'Blocks';
        case 'fused-note': return 'Blocks';
        default: return 'Other';
    }
}

function getPriorityColor(priority?: string): string {
    switch (priority) {
        case 'urgent': return 'var(--danger)';
        case 'high': return 'var(--warn)';
        case 'medium': return 'var(--accent)';
        case 'low': return 'var(--ok)';
        default: return 'transparent';
    }
}

export const SearchResults = memo(function SearchResults({ query, onClose }: SearchResultsProps) {
    const nodes = useStore(s => s.nodes);
    const navigateToNode = useStore(s => s.navigateToNode);
    const setFullscreenId = useStore(s => s.setFullscreenId);
    const setRightSidePanelId = useStore(s => s.setRightSidePanelId);
    const setLeftSidePanelId = useStore(s => s.setLeftSidePanelId);
    const setCenterPanelId = useStore(s => s.setCenterPanelId);

    const [results, setResults] = useState<RichSearchResult[]>([]);
    const [selectedIndex, setSelectedIndex] = useState(0);
    const [isSearching, setIsSearching] = useState(false);
    const debounceTimerRef = useRef<number | null>(null);
    const resultsRef = useRef<HTMLDivElement>(null);

    const worker = useMemo(() => new Worker(new URL('./search.worker.ts', import.meta.url), { type: 'module' }), []);

    useEffect(() => {
        if (!query.trim()) {
            setResults([]);
            setIsSearching(false);
            return;
        }

        setIsSearching(true);

        if (debounceTimerRef.current) {
            clearTimeout(debounceTimerRef.current);
        }

        debounceTimerRef.current = window.setTimeout(() => {
            worker.postMessage({ query, nodes });
        }, 250);

        const handleMessage = (e: MessageEvent) => {
            setResults(e.data.results);
            setSelectedIndex(0);
            setIsSearching(false);
        };

        worker.addEventListener('message', handleMessage);
        return () => {
            worker.removeEventListener('message', handleMessage);
            if (debounceTimerRef.current) {
                clearTimeout(debounceTimerRef.current);
            }
        };
    }, [query, nodes, worker]);

    const handleSelect = useCallback((nodeId: string) => {
        setFullscreenId(null);
        setRightSidePanelId(null);
        setLeftSidePanelId(null);
        setCenterPanelId(null);
        navigateToNode(nodeId);
        onClose();
    }, [setFullscreenId, setRightSidePanelId, setLeftSidePanelId, setCenterPanelId, navigateToNode, onClose]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Enter' && results[selectedIndex]) {
                handleSelect(results[selectedIndex].id);
            } else if (e.key === 'Escape') {
                onClose();
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [results, selectedIndex, onClose, handleSelect]);

    useEffect(() => {
        if (resultsRef.current && results[selectedIndex]) {
            const el = resultsRef.current.querySelector(`[data-index="${selectedIndex}"]`);
            el?.scrollIntoView({ block: 'nearest' });
        }
    }, [selectedIndex, results]);

    const groupedResults: GroupedResults[] = useMemo(() => {
        const groups: Record<string, RichSearchResult[]> = {};
        results.forEach(r => {
            const key = r.type === 'fused-note' ? 'block' : r.type;
            if (!groups[key]) groups[key] = [];
            groups[key].push(r);
        });
        const order = ['note', 'kanban', 'block'];
        return order
            .filter(t => groups[t])
            .map(t => ({
                label: getTypeLabel(t),
                type: t,
                icon: getTypeIcon(t),
                results: groups[t]
            }));
    }, [results]);

    const maxScore = useMemo(() => {
        if (results.length === 0) return 0;
        return Math.max(...results.map(r => r.score));
    }, [results]);

    if (!query.trim()) return null;

    return (
        <div className={styles.searchResults} ref={resultsRef}>
            <div className={styles.searchResultsHeader}>
                <Search size={14} />
                <span>
                    {isSearching ? 'Searching...' : `${results.length} result${results.length !== 1 ? 's' : ''}`}
                </span>
                {results.length > 0 && (
                    <span className={styles.searchResultsHint}>
                        <kbd>↑↓</kbd> navigate <kbd>↵</kbd> open
                    </span>
                )}
            </div>

            {isSearching && results.length === 0 && (
                <div className={styles.searchLoading}>
                    <div className={styles.searchLoadingDots}>
                        <span /><span /><span />
                    </div>
                </div>
            )}

            {!isSearching && results.length === 0 && (
                <div className={styles.searchEmpty}>
                    <Search size={24} />
                    <span>No results found</span>
                    <span className={styles.searchEmptyHint}>
                        Try different keywords or{' '}
                        <span onClick={() => {
                            const input = document.querySelector(`.${styles.searchInput}`) as HTMLInputElement;
                            if (input) {
                                input.value = '';
                                input.focus();
                            }
                        }}>clear filters</span>
                    </span>
                </div>
            )}

            {groupedResults.map((group, groupIndex) => {
                const groupStartIndex = groupedResults
                    .slice(0, groupIndex)
                    .reduce((sum, g) => sum + g.results.length, 0);

                return (
                    <div key={group.type} className={styles.searchGroup}>
                        <div className={styles.searchGroupHeader}>
                            <group.icon size={14} />
                            <span>{group.label}</span>
                            <span className={styles.searchGroupCount}>{group.results.length}</span>
                        </div>
                        {group.results.map((result, idx) => {
                            const globalIndex = groupStartIndex + idx;
                            const isSelected = globalIndex === selectedIndex;
                            const Icon = getTypeIcon(result.type);

                            return (
                                <div
                                    key={result.id}
                                    data-index={globalIndex}
                                    className={`${styles.resultItem} ${isSelected ? styles.selected : ''}`}
                                    onClick={() => handleSelect(result.id)}
                                    onMouseEnter={() => setSelectedIndex(globalIndex)}
                                >
                                    <div className={styles.resultCardAccent}
                                        style={{
                                            background: result.type === 'note'
                                                ? 'linear-gradient(180deg, #ff5040, #ff5040)'
                                                : result.type === 'kanban'
                                                ? 'linear-gradient(180deg, #f59e0b, #d97706)'
                                                : 'linear-gradient(180deg, #ff5040, #ff5040)'
                                        }}
                                    />
                                    <div className={styles.resultIcon}>
                                        <Icon size={16} />
                                    </div>
                                    <div className={styles.resultContent}>
                                        <div className={styles.resultTitleRow}>
                                            <span
                                                className={styles.resultTitle}
                                                dangerouslySetInnerHTML={{
                                                    __html: highlightMatch(result.label, parseSearchQuery(query).text)
                                                }}
                                            />
                                            {result.status && (
                                                <span className={`${styles.resultBadge} ${styles[`status_${result.status}`] || ''}`}>
                                                    {result.status}
                                                </span>
                                            )}
                                        </div>

                                        <div className={styles.resultMeta}>
                                            {result.priority && (
                                                <span className={styles.metaItem}>
                                                    <span className={styles.priorityDot}
                                                        style={{ background: getPriorityColor(result.priority) }}
                                                    />
                                                    {result.priority}
                                                </span>
                                            )}
                                            {result.tags?.slice(0, 3).map((tag: string) => (
                                                <span key={tag} className={styles.metaItem}>
                                                    <Hash size={10} /> {tag}
                                                </span>
                                            ))}
                                            {result.tags && result.tags.length > 3 && (
                                                <span className={styles.metaItem}>+{result.tags.length - 3}</span>
                                            )}
                                            {result.updatedAt && (
                                                <span className={styles.metaItem}>
                                                    <Clock size={10} /> {formatDate(result.updatedAt)}
                                                </span>
                                            )}
                                            {result.wordCount !== undefined && result.wordCount > 0 && (
                                                <span className={styles.metaItem}>
                                                    {result.wordCount} words
                                                </span>
                                            )}
                                        </div>

                                        {result.previewContext && (
                                            <div className={styles.resultPreview}>
                                                <span dangerouslySetInnerHTML={{
                                                    __html: highlightMatch(result.previewContext, parseSearchQuery(query).text)
                                                }} />
                                            </div>
                                        )}

                                        {result.path && result.path.length > 1 && (
                                            <div className={styles.resultPath}>
                                                <CornerDownRight size={10} />
                                                {result.path.slice(0, -1).map((seg, i) => (
                                                    <span key={seg.id} className={styles.pathSegment}>
                                                        {seg.label}
                                                        {i < result.path.length - 2 && (
                                                            <span className={styles.pathSeparator}>/</span>
                                                        )}
                                                    </span>
                                                ))}
                                            </div>
                                        )}
                                    </div>

                                    <div className={styles.resultRight}>
                                        <div className={styles.scoreBar}>
                                            <div
                                                className={styles.scoreBarFill}
                                                style={{ width: `${getScoreWidth(result.score, maxScore)}%` }}
                                            />
                                        </div>
                                        {isSelected && <ChevronRight size={14} className={styles.enterIcon} />}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                );
            })}
        </div>
    );
});

import { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { 
    X, 
    Search,
    ChevronDown, 
    FileText, 
    Folder, 
    Squircle,
    Sparkles, 
    Lock, 
    Star, 
    Plus, 
    MoreHorizontal, 
    Grid3x3, 
    ChevronsUpDown, 
    ChevronsDownUp,
    Trash2, 
    Copy, 
    Edit3,
    CheckSquare,
    Square,
    Quote,
    Code,
    Info,
    Play,
    Columns2,
    Table,
    Image,
    Link
} from '../../components/icons';
import { useReactFlow } from '@xyflow/react';
import { useStore } from '../../store/useStore';
import { useContentNodes } from '../../store/useContentNodes';
import { getNodeBlocks } from '../../types';
import { buildTOCTree, type OutlineItem } from '../../services/tocService';
import styles from './TableOfContentsPanel.module.css';

interface TableOfContentsPanelProps {
    isOpen: boolean;
    onClose: () => void;
    buttonRef?: React.RefObject<HTMLButtonElement | null>;
}

export function TableOfContentsPanel({ isOpen, onClose, buttonRef }: TableOfContentsPanelProps) {
    const nodes = useContentNodes();
    const currentParentId = useStore(s => s.currentParentId);
    const authEmail = useStore(s => s.auth.email);
    const authDisplayName = useStore(s => s.auth.displayName);
    const addNode = useStore(s => s.addNode);
    const updateNodeData = useStore(s => s.updateNodeData);
    const requestNodeDeletion = useStore(s => s.requestNodeDeletion);
    const bulkDuplicateNodes = useStore(s => s.bulkDuplicateNodes);
    const setSelectedCanvasNodeIds = useStore(s => s.setSelectedCanvasNodeIds);

    const { setCenter, fitView, screenToFlowPosition } = useReactFlow();
    const panelRef = useRef<HTMLDivElement>(null);

    // Resizable panel width state
    const [panelWidth, setPanelWidth] = useState(320);

    // State
    const [collapsedItems, setCollapsedItems] = useState<Set<string>>(new Set());
    const [activeItemId, setActiveItemId] = useState<string | null>(null);
    const [hoveredItemId, setHoveredItemId] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [contextMenu, setContextMenu] = useState<{ x: number; y: number; item: OutlineItem } | null>(null);

    // Handle Drag Resizing (docked on the right side of the canvas)
    const handleMouseDown = useCallback((e: React.MouseEvent) => {
        e.preventDefault();
        const startX = e.clientX;
        const startWidth = panelWidth;

        if (panelRef.current) {
            panelRef.current.style.transition = 'none';
        }

        const handleMouseMove = (moveEvent: MouseEvent) => {
            // Dragging handle leftwards increases the width of a right-docked panel
            const delta = startX - moveEvent.clientX;
            const nextWidth = Math.min(Math.max(260, startWidth + delta), 650);
            setPanelWidth(nextWidth);
        };

        const handleMouseUp = () => {
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
            document.body.style.cursor = '';
            document.body.style.userSelect = '';

            if (panelRef.current) {
                panelRef.current.style.transition = '';
            }
        };

        document.addEventListener('mousemove', handleMouseMove);
        document.addEventListener('mouseup', handleMouseUp);
        document.body.style.cursor = 'col-resize';
        document.body.style.userSelect = 'none';
    }, [panelWidth]);

    // Dynamic display name for user / workspace pill
    const displayName = useMemo(() => {
        if (authDisplayName) return authDisplayName;
        if (!authEmail) return 'Morgan Regior';
        const namePart = authEmail.split('@')[0];
        return namePart
            .split(/[._-]/)
            .map((w: string) => w.charAt(0).toUpperCase() + w.slice(1))
            .join(' ') || 'Morgan Regior';
    }, [authDisplayName, authEmail]);

    // Live outline tree strictly built from the current canvas nodes
    const tocTree = useMemo(() => {
        if (!isOpen) return [];
        return buildTOCTree(currentParentId, nodes);
    }, [currentParentId, nodes, isOpen]);

    // Search filtering
    const filteredTOC = useMemo(() => {
        if (!searchQuery.trim()) return tocTree;
        const q = searchQuery.toLowerCase();

        const filterNode = (item: OutlineItem): OutlineItem | null => {
            const labelMatches = item.label.toLowerCase().includes(q);
            const filteredChildren = item.children
                ? item.children.map(filterNode).filter(Boolean) as OutlineItem[]
                : [];

            if (labelMatches || filteredChildren.length > 0) {
                return {
                    ...item,
                    children: filteredChildren
                };
            }
            return null;
        };

        return tocTree.map(filterNode).filter(Boolean) as OutlineItem[];
    }, [tocTree, searchQuery]);

    // Toggle collapse/expand for individual item
    const toggleCollapse = useCallback((id: string, e: React.MouseEvent) => {
        e.stopPropagation();
        setCollapsedItems(prev => {
            const next = new Set(prev);
            if (next.has(id)) {
                next.delete(id);
            } else {
                next.add(id);
            }
            return next;
        });
    }, []);

    // Toggle all items collapse/expand
    const toggleExpandAll = useCallback(() => {
        if (collapsedItems.size > 0) {
            setCollapsedItems(new Set());
        } else {
            const allParentIds = new Set<string>();
            const collectParentIds = (items: OutlineItem[]) => {
                items.forEach(item => {
                    if (item.children && item.children.length > 0) {
                        allParentIds.add(item.id);
                        collectParentIds(item.children);
                    }
                });
            };
            collectParentIds(tocTree);
            setCollapsedItems(allParentIds);
        }
    }, [collapsedItems.size, tocTree]);

    // Toggle Todo status directly from TOC
    const toggleTodoStatus = useCallback((item: OutlineItem, e: React.MouseEvent) => {
        e.stopPropagation();
        const blockId = item.id;
        const ownerNode = nodes.find(n => getNodeBlocks(n.data)?.some(b => b.id === blockId));

        if (ownerNode) {
            const content = (getNodeBlocks(ownerNode.data) ?? []).map((b) => {
                if (b.id === blockId) {
                    return {
                        ...b,
                        metadata: {
                            ...b.metadata,
                            checked: !b.metadata?.checked
                        }
                    };
                }
                return b;
            });

            updateNodeData(ownerNode.id, { content });
            window.dispatchEvent(new CustomEvent('chnk-it-force-editor-sync'));
        }
    }, [nodes, updateNodeData]);

    // Create New Card
    const handleAddNew = useCallback(() => {
        const centerPos = screenToFlowPosition({
            x: window.innerWidth / 2,
            y: window.innerHeight / 2
        });
        addNode('note', centerPos, { label: 'Untitled Note' }, undefined, currentParentId || undefined);
    }, [screenToFlowPosition, addNode, currentParentId]);

    // Add Child inside a specific node
    const handleAddChild = useCallback((parentItem: OutlineItem, e: React.MouseEvent) => {
        e.stopPropagation();
        const parentNode = nodes.find(n => n.id === parentItem.nodeId || n.id === parentItem.id);
        const position = parentNode 
            ? { x: parentNode.position.x + 36, y: parentNode.position.y + 100 }
            : screenToFlowPosition({ x: window.innerWidth / 2, y: window.innerHeight / 2 });

        addNode('note', position, { label: 'New Card' }, undefined, parentItem.nodeId || parentItem.id);
        setCollapsedItems(prev => {
            const next = new Set(prev);
            next.delete(parentItem.id);
            return next;
        });
    }, [nodes, screenToFlowPosition, addNode]);

    // Focus and select the element on the canvas
    const handleItemClick = useCallback((item: OutlineItem) => {
        setActiveItemId(item.id);
        
        // Find owner node
        const ownerNode = nodes.find(n => 
            n.id === item.id || 
            n.id === item.nodeId || 
            getNodeBlocks(n.data)?.some(b => b.id === item.id)
        );

        if (ownerNode) {
            // Select the node on canvas
            setSelectedCanvasNodeIds(new Set([ownerNode.id]));

            const width = (ownerNode.style?.width as number) || 420;
            const height = (ownerNode.style?.height as number) || 300;
            const x = ownerNode.position.x + width / 2;
            const y = ownerNode.position.y + height / 2;

            setCenter(x, y, { zoom: 1.15, duration: 600 });

            // Trigger highlight flash on the card
            const cardEl = document.getElementById(ownerNode.id);
            if (cardEl) {
                cardEl.classList.add('chnk-it-highlight-flash');
                setTimeout(() => cardEl.classList.remove('chnk-it-highlight-flash'), 1600);
            }

            // If it's a specific block inside the card, scroll to it and highlight
            if (item.targetId && item.targetId.startsWith('block-')) {
                setTimeout(() => {
                    const blockEl = document.getElementById(item.targetId);
                    if (blockEl) {
                        blockEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        blockEl.classList.add('chnk-it-highlight-flash');
                        setTimeout(() => blockEl.classList.remove('chnk-it-highlight-flash'), 1600);
                    }
                }, 350);
            }
        }
    }, [nodes, setCenter, setSelectedCanvasNodeIds]);

    // Context Menu Trigger
    const openContextMenu = useCallback((item: OutlineItem, e: React.MouseEvent) => {
        e.stopPropagation();
        const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
        setContextMenu({
            x: rect.left,
            y: rect.bottom + 4,
            item
        });
    }, []);

    // Outside click listener
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (contextMenu) {
                setContextMenu(null);
            }
            if (!isOpen) return;

            const clickedInsidePanel = panelRef.current?.contains(e.target as Node);
            const clickedOnButton = buttonRef?.current?.contains(e.target as Node);
            const clickedInMenu = (e.target as HTMLElement | null)?.closest?.('[data-app-menu]');

            if (!clickedInsidePanel && !clickedOnButton && !clickedInMenu && !contextMenu) {
                onClose();
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isOpen, onClose, buttonRef, contextMenu]);

    // Render node icons:
    // Card -> Folder icon
    // Fused node -> File icon
    // Headers -> H1, H2, H3 badges
    // Bullet -> Bullet dot
    // Numbered -> Sequential number badge
    // Todo -> Interactive CheckSquare / Square
    const renderNodeIcon = (item: OutlineItem) => {
        if (item.type === 'card' || item.type === 'page' || item.nodeType === 'note') {
            return <Folder size={14} className={styles.iconFolder} />;
        }
        if (item.type === 'fused-note' || item.nodeType === 'fused-note') {
            return <FileText size={14} className={styles.iconFile} />;
        }
        if (item.type === 'kanban' || item.nodeType === 'kanban') {
            return <Columns2 size={14} className={styles.iconFile} />;
        }

        switch (item.iconVariant) {
            case 'h1':
                return <span className={styles.headingBadge}>H1</span>;
            case 'h2':
                return <span className={styles.headingBadge}>H2</span>;
            case 'h3':
                return <span className={styles.headingBadge}>H3</span>;
            case 'bullet':
                return <span className={styles.bulletDot}>•</span>;
            case 'numbered':
                return <span className={styles.numberBadge}>{item.listIndex !== undefined ? `${item.listIndex}.` : '1.'}</span>;
            case 'todo':
                return item.checked ? (
                    <span 
                        title="Mark incomplete"
                        onClick={(e) => toggleTodoStatus(item, e)}
                        className={styles.todoIconWrapper}
                    >
                        <CheckSquare size={13} className={styles.todoChecked} />
                    </span>
                ) : (
                    <span 
                        title="Mark complete"
                        onClick={(e) => toggleTodoStatus(item, e)}
                        className={styles.todoIconWrapper}
                    >
                        <Square size={13} className={styles.todoUnchecked} />
                    </span>
                );
            case 'quote':
                return <Quote size={12} className={styles.iconBlock} />;
            case 'code':
                return <Code size={13} className={styles.iconBlock} />;
            case 'callout':
                return <Info size={13} className={styles.iconBlock} />;
            case 'toggle':
                return <Play size={10} style={{ transform: 'rotate(90deg)' }} className={styles.iconBlock} />;
            case 'table':
                return <Table size={13} className={styles.iconBlock} />;
            case 'image':
                return <Image size={13} className={styles.iconBlock} />;
            case 'link':
                return <Link size={13} className={styles.iconBlock} />;
            case 'ai':
                return <Sparkles size={13} className={styles.iconBlock} />;
            case 'file':
                return <FileText size={14} className={styles.iconFile} />;
            case 'folder':
                return <Folder size={14} className={styles.iconFolder} />;
            default:
                return <Squircle size={13} className={styles.iconBlock} />;
        }
    };

    // Recursive Tree Node Renderer
    const renderTreeNode = (item: OutlineItem, depth = 0) => {
        const hasChildren = item.children && item.children.length > 0;
        const isCollapsed = collapsedItems.has(item.id) && !searchQuery;
        const isActive = activeItemId === item.id;
        const isCompletedTodo = item.type === 'todo' && item.checked;

        return (
            <div key={item.id} className={styles.nodeItemWrapper}>
                {/* Branch elbow connector line */}
                {depth > 0 && (
                    <div 
                        className={styles.branchElbow} 
                        style={{ left: `${(depth - 1) * 16 + 12}px` }} 
                    />
                )}

                <div 
                    className={`
                        ${styles.nodeRow} 
                        ${isActive ? styles.nodeRowActive : ''}
                    `}
                    style={{ paddingLeft: `${depth * 16 + 6}px` }}
                    onClick={() => handleItemClick(item)}
                    onMouseEnter={() => setHoveredItemId(item.id)}
                    onMouseLeave={() => setHoveredItemId(null)}
                >
                    {/* Expand/Collapse Caret */}
                    {hasChildren ? (
                        <button 
                            className={`
                                ${styles.expandBtn} 
                                ${isCollapsed ? styles.expandBtnCollapsed : styles.expandBtnExpanded}
                            `}
                            onClick={(e) => toggleCollapse(item.id, e)}
                            title={isCollapsed ? "Expand" : "Collapse"}
                        >
                            <ChevronDown size={13} />
                        </button>
                    ) : (
                        <div style={{ width: 14, flexShrink: 0 }} />
                    )}

                    {/* Node Icon */}
                    <div className={styles.nodeIcon}>
                        {renderNodeIcon(item)}
                    </div>

                    {/* Node Label */}
                    <span className={`
                        ${styles.nodeLabel} 
                        ${isActive ? styles.nodeLabelActive : ''}
                        ${isCompletedTodo ? styles.todoCompletedText : ''}
                    `}>
                        {item.label}
                    </span>

                    {/* Lock Icon */}
                    {item.isLocked && (
                        <span className={styles.lockIcon} title="Locked item">
                            <Lock size={12} />
                        </span>
                    )}

                    {/* Right-aligned Meta (Counters or Favorite Star) */}
                    <div className={styles.rightMeta}>
                        {item.isFavorite && (
                            <Star size={13} className={styles.starBadge} />
                        )}
                        {item.childCount !== undefined && !item.isFavorite && (
                            <span className={styles.countText}>
                                {item.childCount}
                            </span>
                        )}
                    </div>

                    {/* Hover Quick Actions */}
                    <div className={styles.hoverActions}>
                        <button 
                            className={styles.quickActionBtn}
                            onClick={(e) => handleAddChild(item, e)}
                            title="Add sub-item"
                        >
                            <Plus size={13} />
                        </button>
                        <button 
                            className={styles.quickActionBtn}
                            onClick={(e) => openContextMenu(item, e)}
                            title="Options"
                        >
                            <MoreHorizontal size={13} />
                        </button>
                    </div>
                </div>

                {/* Recursive Children with branch guide */}
                {hasChildren && !isCollapsed && (
                    <div className={styles.treeWrapper}>
                        {/* Vertical line guide for children */}
                        <div 
                            className={styles.verticalGuideLine} 
                            style={{ left: `${depth * 16 + 12}px` }} 
                        />
                        {item.children.map((child) => 
                            renderTreeNode(child, depth + 1)
                        )}
                    </div>
                )}
            </div>
        );
    };

    const showPanel = isOpen;

    return (
        <div 
            ref={panelRef}
            className={`${styles.panel} ${showPanel ? styles.panelOpen : styles.panelClosed}`}
            style={{ width: showPanel ? panelWidth : 0 }}
        >
            {/* Resize Handle on the left edge */}
            {showPanel && (
                <div 
                    className={styles.resizeHandle}
                    onMouseDown={handleMouseDown}
                    role="separator"
                    aria-orientation="vertical"
                    aria-label="Resize outline panel"
                >
                    <span className={styles.resizeGrip} aria-hidden="true" />
                    <span className={styles.resizeTooltip}>Resize</span>
                </div>
            )}

            {/* Header: Sits on panel chrome matching app topbar */}
            <div className={styles.header}>
                <div className={styles.userChip} title="Workspace Navigator">
                    <div className={styles.avatarContainer}>
                        <img 
                            src="https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=64&h=64&fit=crop&crop=faces" 
                            alt="Avatar" 
                            className={styles.avatarImage} 
                            onError={(e) => {
                                (e.currentTarget as HTMLElement).style.display = 'none';
                            }}
                        />
                    </div>
                    <span className={styles.userNameText}>{displayName}</span>
                    <ChevronsUpDown size={12} className={styles.userChipChevron} />
                </div>

                <div className={styles.headerActions}>
                    <button 
                        className={styles.headerIconBtn} 
                        onClick={toggleExpandAll}
                        title={collapsedItems.size > 0 ? "Expand all" : "Collapse all"}
                    >
                        {collapsedItems.size > 0 ? <ChevronsUpDown size={14} /> : <ChevronsDownUp size={14} />}
                    </button>
                    <button 
                        className={styles.headerIconBtn} 
                        onClick={onClose} 
                        title="Close outline"
                    >
                        <X size={15} />
                    </button>
                </div>
            </div>

            {/* Panel Inset Body */}
            <div className={styles.panelBody}>
                {/* Action Row: + Add new card */}
                <div className={styles.actionRow}>
                    <button className={styles.addNewBtn} onClick={handleAddNew}>
                        <Plus size={14} />
                        <span>Add new</span>
                    </button>
                    <span className={styles.itemCountTotal}>
                        {tocTree.length} {tocTree.length === 1 ? 'item' : 'items'}
                    </span>
                </div>

                {/* Search Bar */}
                <div className={styles.searchContainer}>
                    <Search size={13} className={styles.searchIcon} />
                    <input 
                        type="text" 
                        className={styles.searchInput}
                        placeholder="Search outline..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                    {searchQuery && (
                        <button className={styles.clearSearchBtn} onClick={() => setSearchQuery('')} title="Clear search">
                            <X size={12} />
                        </button>
                    )}
                </div>

                {/* Scrollable Tree Area */}
                <div className={styles.treeScrollArea}>
                    {filteredTOC.length === 0 ? (
                        <div className={styles.emptyState}>
                            <FileText size={26} className={styles.emptyStateIcon} />
                            <span>{searchQuery ? 'No matching items found' : 'No notes on canvas'}</span>
                        </div>
                    ) : (
                        <div className={styles.treeWrapper}>
                            {filteredTOC.map((item) => 
                                renderTreeNode(item, 0)
                            )}
                        </div>
                    )}
                </div>

                {/* Footer: Browse All */}
                <div className={styles.cardFooter}>
                    <button 
                        className={styles.browseAllBtn}
                        onClick={() => fitView({ padding: 0.25, duration: 600 })}
                        title="Fit view to show all canvas items"
                    >
                        <Grid3x3 size={14} />
                        <span>Browse all</span>
                    </button>
                </div>
            </div>

            {/* Context Menu Dropdown */}
            {contextMenu && (
                <div 
                    className={styles.contextMenu}
                    style={{ 
                        left: Math.min(contextMenu.x, window.innerWidth - 160), 
                        top: contextMenu.y 
                    }}
                >
                    <button 
                        className={styles.contextMenuItem}
                        onClick={() => {
                            const newTitle = prompt('Rename note:', contextMenu.item.label);
                            if (newTitle && contextMenu.item.nodeId) {
                                updateNodeData(contextMenu.item.nodeId, { label: newTitle });
                            }
                            setContextMenu(null);
                        }}
                    >
                        <Edit3 size={13} />
                        <span>Rename</span>
                    </button>

                    <button 
                        className={styles.contextMenuItem}
                        onClick={() => {
                            if (contextMenu.item.nodeId) {
                                bulkDuplicateNodes([contextMenu.item.nodeId]);
                            }
                            setContextMenu(null);
                        }}
                    >
                        <Copy size={13} />
                        <span>Duplicate</span>
                    </button>

                    <button 
                        className={styles.contextMenuItem}
                        onClick={() => {
                            if (contextMenu.item.nodeId) {
                                const targetNode = nodes.find(n => n.id === contextMenu.item.nodeId);
                                const isCurrentPinned = (targetNode?.data as any)?.isPinned;
                                updateNodeData(contextMenu.item.nodeId, { isPinned: !isCurrentPinned });
                            }
                            setContextMenu(null);
                        }}
                    >
                        <Star size={13} />
                        <span>Favorite</span>
                    </button>

                    <button 
                        className={styles.contextMenuItem}
                        onClick={() => {
                            if (contextMenu.item.nodeId) {
                                const targetNode = nodes.find(n => n.id === contextMenu.item.nodeId);
                                const isLocked = (targetNode?.data as any)?.isLocked;
                                updateNodeData(contextMenu.item.nodeId, { isLocked: !isLocked });
                            }
                            setContextMenu(null);
                        }}
                    >
                        <Lock size={13} />
                        <span>Toggle Lock</span>
                    </button>

                    <button 
                        className={`${styles.contextMenuItem} ${styles.contextMenuItemDanger}`}
                        onClick={() => {
                            if (contextMenu.item.nodeId) {
                                requestNodeDeletion([contextMenu.item.nodeId]);
                            }
                            setContextMenu(null);
                        }}
                    >
                        <Trash2 size={13} />
                        <span>Delete</span>
                    </button>
                </div>
            )}
        </div>
    );
}

import { type AppNode, getNodeBlocks, getNodeLabel } from '../types';
import type { Block, BlockMetadata } from '../features/editor/types';

export type OutlineIconVariant = 
    | 'folder' 
    | 'file' 
    | 'block' 
    | 'h1' 
    | 'h2' 
    | 'h3' 
    | 'bullet'
    | 'numbered'
    | 'todo' 
    | 'callout' 
    | 'quote' 
    | 'code' 
    | 'toggle' 
    | 'table'
    | 'image'
    | 'link'
    | 'ai';

export interface OutlineItem {
    id: string;
    type: string;
    label: string;
    targetId: string; // The DOM element ID or node ID to scroll to
    children: OutlineItem[];
    indent: number;
    headingLevel: number; // 1 for H1/Cards, 2 for H2, 3 for H3, 4 for others
    nodeId?: string; // Owner or target node ID
    checked?: boolean; // For checklist items
    listIndex?: number; // For numbered lists
    metadata?: BlockMetadata; // Raw block metadata
    isFolder?: boolean;
    childCount?: number;
    isLocked?: boolean;
    isFavorite?: boolean;
    iconVariant: OutlineIconVariant;
    nodeType?: string;
}

/**
 * Strips HTML tags, Markdown symbols (bold, italic, code, quotes, headers),
 * and leading markers from text for clean outline presentation.
 */
export function cleanBlockContent(raw: string | undefined): string {
    if (!raw) return '';
    return raw
        .replace(/<[^>]*>?/gm, '') // Strip HTML tags
        .replace(/[*_~`#]/g, '')   // Strip markdown markers like **, *, _, ~~, `, #
        .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1') // [text](url) -> text
        .replace(/^\s*[-*+•]\s+/, '') // Strip leading bullet markers
        .replace(/^\s*\d+\.\s+/, '') // Strip leading number prefixes like "1. "
        .replace(/&nbsp;/g, ' ')
        .replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .trim();
}

/**
 * Sorts canvas nodes visually by visual Y-coordinate, then X-coordinate.
 */
function sortNodesVisually(nodes: AppNode[]): AppNode[] {
    return [...nodes].sort((a, b) => {
        if (Math.abs(a.position.y - b.position.y) < 24) {
            return a.position.x - b.position.x;
        }
        return a.position.y - b.position.y;
    });
}

/**
 * Determines an icon variant for blocks inside a node.
 */
function determineBlockIconVariant(blockType: string): OutlineIconVariant {
    switch (blockType) {
        case 'heading1':
            return 'h1';
        case 'heading2':
            return 'h2';
        case 'heading3':
            return 'h3';
        case 'bullet':
            return 'bullet';
        case 'numbered':
            return 'numbered';
        case 'todo':
            return 'todo';
        case 'callout':
            return 'callout';
        case 'quote':
            return 'quote';
        case 'code':
            return 'code';
        case 'toggle':
            return 'toggle';
        case 'table':
            return 'table';
        case 'image':
        case 'video':
        case 'media':
            return 'image';
        case 'link':
            return 'link';
        case 'ai':
            return 'ai';
        default:
            return 'block';
    }
}

/**
 * Parses blocks inside a single card/note into outline items.
 */
function parseBlocksInsideNode(
    blocks: Block[],
    ownerNodeId: string,
    allNodes: AppNode[],
    baseLevel = 1
): OutlineItem[] {
    const items: OutlineItem[] = [];
    let i = 0;
    let sequentialListIndex = 1;

    while (i < blocks.length) {
        const block = blocks[i];
        const isHeading = ['heading1', 'heading2', 'heading3'].includes(block.type);
        const isToggle = block.type === 'toggle';
        const isPage = block.type === 'page';
        const isTodo = block.type === 'todo';
        const isBullet = block.type === 'bullet';
        const isNumbered = block.type === 'numbered';
        const isCallout = block.type === 'callout';
        const isQuote = block.type === 'quote';
        const isCode = block.type === 'code';

        if (isNumbered) {
            sequentialListIndex++;
        } else {
            sequentialListIndex = 1;
        }

        const isSupported = isHeading || isToggle || isPage || isTodo || isBullet || isNumbered || isCallout || isQuote || isCode || block.content?.trim();

        if (isSupported) {
            let headingLevel = 4;
            if (block.type === 'heading1') headingLevel = 1;
            else if (block.type === 'heading2') headingLevel = 2;
            else if (block.type === 'heading3') headingLevel = 3;

            let children: OutlineItem[] = [];

            // 1. Indented children for toggles
            if (isToggle) {
                const toggleIndent = block.indent || 0;
                const toggleChildrenBlocks: Block[] = [];
                let j = i + 1;
                while (j < blocks.length && (blocks[j].indent || 0) > toggleIndent) {
                    toggleChildrenBlocks.push(blocks[j]);
                    j++;
                }
                if (toggleChildrenBlocks.length > 0) {
                    children = parseBlocksInsideNode(toggleChildrenBlocks, ownerNodeId, allNodes, baseLevel + 1);
                }
                i = j - 1;
            }

            // 2. Recursive page children (sub-notes)
            if (isPage && block.metadata?.nodeId) {
                const subId = block.metadata.nodeId;
                const subNode = allNodes.find(n => n.id === subId);
                if (subNode) {
                    const subBlocks = getNodeBlocks(subNode.data) || [];
                    const directChildNodes = allNodes.filter(n => n.parentId === subId);
                    const subItems = parseBlocksInsideNode(subBlocks, subId, allNodes, baseLevel + 1);
                    const childNodeItems = directChildNodes.map(cn => buildNodeItem(cn, allNodes, baseLevel + 1));
                    children = [...subItems, ...childNodeItems];
                }
            }

            const rawContent = block.content || (block.type === 'page' ? 'Untitled Page' : '');
            const cleanLabel = cleanBlockContent(rawContent) || (block.type === 'page' ? 'Untitled Page' : (block.type.charAt(0).toUpperCase() + block.type.slice(1)));

            items.push({
                id: block.id,
                type: block.type,
                label: cleanLabel,
                targetId: block.type === 'page' ? (block.metadata?.nodeId || block.id) : `block-${block.id}`,
                children,
                indent: block.indent || 0,
                headingLevel,
                nodeId: block.metadata?.nodeId || ownerNodeId,
                checked: block.metadata?.checked || false,
                listIndex: isNumbered ? (sequentialListIndex - 1) : undefined,
                metadata: block.metadata,
                isFolder: isPage || children.length > 0,
                childCount: children.length > 0 ? children.length : undefined,
                iconVariant: isPage ? 'folder' : determineBlockIconVariant(block.type)
            });
        }
        i++;
    }

    return nestHeadingHierarchy(items);
}

/**
 * Builds an outline item for a top-level or child AppNode.
 */
function buildNodeItem(node: AppNode, allNodes: AppNode[], level = 0): OutlineItem {
    const rawLabel = getNodeLabel(node.data) || (node.data as any)?.title || (node.type === 'fused-note' ? 'Fused File' : 'Untitled');
    const cleanLabel = cleanBlockContent(typeof rawLabel === 'string' ? rawLabel : '') || (node.type === 'fused-note' ? 'Fused File' : 'Untitled');
    
    // Child nodes in canvas tree
    const childNodes = allNodes.filter(n => n.parentId === node.id);
    const sortedChildNodes = sortNodesVisually(childNodes);
    const childNodeItems = sortedChildNodes.map(child => buildNodeItem(child, allNodes, level + 1));

    // Internal blocks inside node
    const contentBlocks = getNodeBlocks(node.data) || [];
    const blockItems = parseBlocksInsideNode(contentBlocks, node.id, allNodes, level + 1);

    const children = [...childNodeItems, ...blockItems];
    const totalChildCount = (childNodes.length > 0 ? childNodes.length : 0) + (blockItems.length > 0 ? blockItems.length : 0);

    // Specific user rule:
    // Card (node.type === 'note') -> Folder icon
    // Fused node (node.type === 'fused-note') -> File icon
    // Block -> Block icon
    let iconVariant: OutlineIconVariant = 'folder';
    if (node.type === 'fused-note') {
        iconVariant = 'file';
    } else if (node.type === 'block') {
        iconVariant = 'block';
    } else if (node.type === 'note') {
        iconVariant = 'folder';
    }

    const isLocked = !!(node.data as any)?.isLocked || !!(node.data as any)?.locked;
    const isFavorite = !!(node.data as any)?.isPinned || (node.data as any)?.priority === 'urgent';

    return {
        id: node.id,
        type: node.type as OutlineItem['type'],
        label: cleanLabel,
        targetId: node.id,
        children,
        indent: level,
        headingLevel: 1,
        nodeId: node.id,
        isFolder: children.length > 0,
        childCount: totalChildCount > 0 ? totalChildCount : undefined,
        isLocked,
        isFavorite,
        iconVariant,
        nodeType: node.type
    };
}

/**
 * Logically nests headings (H2 under H1, H3 under H2) in an outline item tree.
 */
function nestHeadingHierarchy(items: OutlineItem[]): OutlineItem[] {
    const nested: OutlineItem[] = [];
    const stack: OutlineItem[] = [];

    items.forEach(item => {
        if (item.children && item.children.length > 0) {
            item.children = nestHeadingHierarchy(item.children);
        }

        const isHeading = ['heading1', 'heading2', 'heading3'].includes(item.type);
        if (!isHeading) {
            if (stack.length > 0) {
                stack[stack.length - 1].children.push(item);
            } else {
                nested.push(item);
            }
            return;
        }

        const currentLevel = item.headingLevel;

        while (stack.length > 0 && stack[stack.length - 1].headingLevel >= currentLevel) {
            stack.pop();
        }

        if (stack.length > 0) {
            stack[stack.length - 1].children.push(item);
        } else {
            nested.push(item);
        }

        stack.push(item);
    });

    return nested;
}

/**
 * Builds the complete outline tree for a page/node or whole current canvas context.
 */
export function buildTOCTree(nodeId: string | null, allNodes: AppNode[], level = 0): OutlineItem[] {
    // If drilled down inside a specific parent card context
    if (nodeId) {
        const parentNode = allNodes.find(n => n.id === nodeId);
        const childNodes = allNodes.filter(n => n.parentId === nodeId);
        const sortedChildNodes = sortNodesVisually(childNodes);
        const childItems = sortedChildNodes.map(child => buildNodeItem(child, allNodes, level));

        const contentBlocks = parentNode ? (getNodeBlocks(parentNode.data) || []) : [];
        const blockItems = parentNode ? parseBlocksInsideNode(contentBlocks, parentNode.id, allNodes, level) : [];

        return [...childItems, ...blockItems];
    }

    // Root context: gather all top-level nodes on canvas (parentId is null or undefined)
    const rootNodes = allNodes.filter(n => !n.parentId);
    const validRootNodes = rootNodes.filter(n => 
        ['note', 'fused-note', 'block', 'kanban'].includes(n.type)
    );

    const sortedRoots = sortNodesVisually(validRootNodes);
    return sortedRoots.map(node => buildNodeItem(node, allNodes, level));
}
